using System;
using System.Collections.Generic;

namespace RTC.Api
{
    public sealed class RtcValue
    {
        private static readonly RtcValue NullInstance = new RtcValue(RtcValueKind.Null);

        // GC：空 Map/Array 单例。心跳应答、空 Answer、空容器解码等高频路径复用，
        // 避免每次分配空数组 + RtcValue 对象（MapValue/ArrayValue 为空数组，无内容可改，安全）。
        internal static readonly RtcValue EmptyMap =
            new RtcValue(RtcValueKind.Map) { MapValue = Array.Empty<RtcField>() };
        internal static readonly RtcValue EmptyArray =
            new RtcValue(RtcValueKind.Array) { ArrayValue = Array.Empty<RtcValue>() };

        private RtcValue(RtcValueKind kind)
        {
            Kind = kind;
        }

        public RtcValueKind Kind { get; }

        public bool BooleanValue { get; private set; }
        public long Int64Value { get; private set; }
        public double DoubleValue { get; private set; }
        public string StringValue { get; private set; }
        public byte[] BinaryValue { get; private set; }
        public RtcValue[] ArrayValue { get; private set; }
        public RtcField[] MapValue { get; private set; }

        public static RtcValue Null()
        {
            return NullInstance;
        }

        public static RtcValue Of(bool value)
        {
            return new RtcValue(RtcValueKind.Boolean) { BooleanValue = value };
        }

        public static RtcValue Of(long value)
        {
            return new RtcValue(RtcValueKind.Int64) { Int64Value = value };
        }

        public static RtcValue Of(double value)
        {
            return new RtcValue(RtcValueKind.Double) { DoubleValue = value };
        }

        public static RtcValue Of(string value)
        {
            if (value == null)
            {
                throw new ArgumentNullException(nameof(value));
            }

            return new RtcValue(RtcValueKind.String) { StringValue = value };
        }

        public static RtcValue Of(byte[] value)
        {
            if (value == null)
            {
                throw new ArgumentNullException(nameof(value));
            }

            return new RtcValue(RtcValueKind.Binary) { BinaryValue = value };
        }

        public static RtcValue OfArray(IReadOnlyList<RtcValue> items)
        {
            if (items == null)
            {
                throw new ArgumentNullException(nameof(items));
            }

            if (items.Count == 0)
            {
                return EmptyArray;
            }

            var copied = new RtcValue[items.Count];
            for (int i = 0; i < items.Count; i++)
            {
                copied[i] = items[i];
            }

            return new RtcValue(RtcValueKind.Array) { ArrayValue = copied };
        }

        // 质量改进项 2.2：long 列表便捷重载。
        // 消除 RtcClient 各域（Room/Group/Conversation）里手写
        // "new RtcValue[n]; for ... items[i] = Of(ids[i]);" 的 8+ 处重复代码。
        public static RtcValue OfArray(IReadOnlyList<long> values)
        {
            if (values == null)
            {
                throw new ArgumentNullException(nameof(values));
            }

            if (values.Count == 0)
            {
                return EmptyArray;
            }

            var items = new RtcValue[values.Count];
            for (int i = 0; i < values.Count; i++)
            {
                items[i] = Of(values[i]);
            }

            return new RtcValue(RtcValueKind.Array) { ArrayValue = items };
        }

        public static RtcValue OfMap(IReadOnlyList<RtcField> fields)
        {
            if (fields == null)
            {
                throw new ArgumentNullException(nameof(fields));
            }

            if (fields.Count == 0)
            {
                return EmptyMap;
            }

            var copied = new RtcField[fields.Count];
            for (int i = 0; i < fields.Count; i++)
            {
                copied[i] = fields[i];
            }

            return new RtcValue(RtcValueKind.Map) { MapValue = copied };
        }

        // GC-4：跳过防御性拷贝的 internal 构造。调用方（如 RtcMsgPackReader）已持有
        // 独占数组，无需再复制一份。仅 SDK 内部使用（internal），不对外暴露。
        internal static RtcValue OfArrayDirect(RtcValue[] ownedItems)
        {
            return ownedItems.Length == 0
                ? EmptyArray
                : new RtcValue(RtcValueKind.Array) { ArrayValue = ownedItems };
        }

        // The caller transfers ownership of ownedFields to the returned value.
        // The array must not be modified or reused after this call.
        public static RtcValue OfMapDirect(RtcField[] ownedFields)
        {
            if (ownedFields == null)
            {
                throw new ArgumentNullException(nameof(ownedFields));
            }

            return ownedFields.Length == 0
                ? EmptyMap
                : new RtcValue(RtcValueKind.Map) { MapValue = ownedFields };
        }

        // 索引器只在 Kind == Map 时可用；缺失字段返回 Null()，不抛异常
        // （架构文档 3.2 节遗留的行为选择，在这里由测试锁定）。
        public RtcValue this[string fieldName]
        {
            get
            {
                if (Kind != RtcValueKind.Map)
                {
                    throw new InvalidOperationException(
                        "RtcValue 索引器只能在 Kind == Map 时使用，当前 Kind=" + Kind + "。");
                }

                // 质量改进项 1.3：用 for 循环替代 LINQ FirstOrDefault，
                // 消除高频解析路径（History/Conversation）上的 lambda 闭包分配与迭代器分配。
                RtcField[] map = MapValue;
                for (int i = 0; i < map.Length; i++)
                {
                    if (map[i].Name == fieldName)
                    {
                        return map[i].Value;
                    }
                }

                return Null();
            }
        }
    }
}

