using System;
using System.Text;
using RTC.Api;

namespace RTC.Protocol
{
    // Bounded MessagePack reader for the RtcValue ABI.
    internal static class RtcMsgPackReader
    {
        private const int MaxDepth = 32;

        private static readonly UTF8Encoding Utf8Lenient =
            new UTF8Encoding(false, false);

        public static RtcValue Read(byte[] buffer, ref int offset)
        {
            if (buffer == null)
            {
                throw new RtcProtocolException("MessagePack buffer is null.");
            }

            return Read(buffer, buffer.Length, ref offset);
        }

        internal static RtcValue Read(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            if (buffer == null)
            {
                throw new RtcProtocolException("MessagePack buffer is null.");
            }

            if (endOffset < 0 || endOffset > buffer.Length)
            {
                throw new RtcProtocolException("MessagePack end offset is outside the buffer.");
            }

            RequireRemaining(endOffset, ref offset, 0);
            return ReadCore(buffer, endOffset, ref offset, 0);
        }

        private static RtcValue ReadCore(
            byte[] buffer,
            int endOffset,
            ref int offset,
            int depth)
        {
            if (depth > MaxDepth)
            {
                throw new RtcProtocolException(
                    "msgpack nesting too deep (depth " + depth + " > " + MaxDepth + ").");
            }

            byte sign = ReadUInt8(buffer, endOffset, ref offset);

            if (sign <= 0x7f)
            {
                return RtcValue.Of((long)sign);
            }

            if (sign >= 0xe0)
            {
                return RtcValue.Of((long)(sbyte)sign);
            }

            if ((sign & 0xf0) == 0x80)
            {
                return ReadMap(buffer, endOffset, ref offset, sign & 0x0f, depth);
            }

            if ((sign & 0xf0) == 0x90)
            {
                return ReadArray(buffer, endOffset, ref offset, sign & 0x0f, depth);
            }

            if ((sign & 0xe0) == 0xa0)
            {
                return ReadStringValue(buffer, endOffset, ref offset, sign & 0x1f);
            }

            switch (sign)
            {
                case 0xc0:
                    return RtcValue.Null();
                case 0xc2:
                    return RtcValue.Of(false);
                case 0xc3:
                    return RtcValue.Of(true);
                case 0xc4:
                    return ReadBinary(buffer, endOffset, ref offset,
                        ReadUInt8(buffer, endOffset, ref offset));
                case 0xc5:
                    return ReadBinary(buffer, endOffset, ref offset,
                        ReadUInt16BE(buffer, endOffset, ref offset));
                case 0xc6:
                    return ReadBinary(buffer, endOffset, ref offset,
                        unchecked((int)ReadUInt32BE(buffer, endOffset, ref offset)));
                case 0xca:
                    return RtcValue.Of((double)ReadFloat32BE(buffer, endOffset, ref offset));
                case 0xcb:
                    return RtcValue.Of(ReadFloat64BE(buffer, endOffset, ref offset));
                case 0xcc:
                    return RtcValue.Of((long)ReadUInt8(buffer, endOffset, ref offset));
                case 0xcd:
                    return RtcValue.Of((long)ReadUInt16BE(buffer, endOffset, ref offset));
                case 0xce:
                    return RtcValue.Of((long)ReadUInt32BE(buffer, endOffset, ref offset));
                case 0xcf:
                    return RtcValue.Of(unchecked((long)ReadUInt64BE(buffer, endOffset, ref offset)));
                case 0xd0:
                    return RtcValue.Of((long)(sbyte)ReadUInt8(buffer, endOffset, ref offset));
                case 0xd1:
                    return RtcValue.Of((long)ReadInt16BE(buffer, endOffset, ref offset));
                case 0xd2:
                    return RtcValue.Of((long)ReadInt32BE(buffer, endOffset, ref offset));
                case 0xd3:
                    return RtcValue.Of(ReadInt64BE(buffer, endOffset, ref offset));
                case 0xd9:
                    return ReadStringValue(buffer, endOffset, ref offset,
                        ReadUInt8(buffer, endOffset, ref offset));
                case 0xda:
                    return ReadStringValue(buffer, endOffset, ref offset,
                        ReadUInt16BE(buffer, endOffset, ref offset));
                case 0xdb:
                    return ReadStringValue(buffer, endOffset, ref offset,
                        unchecked((int)ReadUInt32BE(buffer, endOffset, ref offset)));
                case 0xdc:
                    return ReadArray(buffer, endOffset, ref offset,
                        ReadUInt16BE(buffer, endOffset, ref offset), depth);
                case 0xdd:
                    return ReadArray(buffer, endOffset, ref offset,
                        unchecked((int)ReadUInt32BE(buffer, endOffset, ref offset)), depth);
                case 0xde:
                    return ReadMap(buffer, endOffset, ref offset,
                        ReadUInt16BE(buffer, endOffset, ref offset), depth);
                case 0xdf:
                    return ReadMap(buffer, endOffset, ref offset,
                        unchecked((int)ReadUInt32BE(buffer, endOffset, ref offset)), depth);
                default:
                    throw new RtcProtocolException(
                        "Unsupported MessagePack type 0x" + sign.ToString("x2") + ".");
            }
        }

        private static RtcValue ReadMap(
            byte[] buffer,
            int endOffset,
            ref int offset,
            int count,
            int depth)
        {
            ValidateFieldLength(count, endOffset - offset, "map");
            if (count == 0)
            {
                return RtcValue.EmptyMap;
            }

            var fields = new RtcField[count];
            for (int i = 0; i < count; i++)
            {
                RtcValue key = ReadCore(buffer, endOffset, ref offset, depth + 1);
                string keyString;
                if (key.Kind == RtcValueKind.String)
                {
                    keyString = key.StringValue;
                }
                else if (key.Kind == RtcValueKind.Int64)
                {
                    keyString = key.Int64Value.ToString();
                }
                else
                {
                    throw new RtcProtocolException(
                        "RTC map keys must be strings or integers.");
                }

                RtcValue value = ReadCore(buffer, endOffset, ref offset, depth + 1);
                fields[i] = RtcField.Of(keyString, value);
            }

            return RtcValue.OfMapDirect(fields);
        }

        private static RtcValue ReadArray(
            byte[] buffer,
            int endOffset,
            ref int offset,
            int count,
            int depth)
        {
            ValidateFieldLength(count, endOffset - offset, "array");
            if (count == 0)
            {
                return RtcValue.EmptyArray;
            }

            var items = new RtcValue[count];
            for (int i = 0; i < count; i++)
            {
                items[i] = ReadCore(buffer, endOffset, ref offset, depth + 1);
            }

            return RtcValue.OfArrayDirect(items);
        }

        private static RtcValue ReadStringValue(
            byte[] buffer,
            int endOffset,
            ref int offset,
            int length)
        {
            ValidateFieldLength(length, endOffset - offset, "string");
            RequireRemaining(endOffset, ref offset, length);
            string value = Utf8Lenient.GetString(buffer, offset, length);
            offset += length;
            return RtcValue.Of(value);
        }

        private static RtcValue ReadBinary(
            byte[] buffer,
            int endOffset,
            ref int offset,
            int length)
        {
            ValidateFieldLength(length, endOffset - offset, "binary");
            RequireRemaining(endOffset, ref offset, length);
            byte[] data = new byte[length];
            Array.Copy(buffer, offset, data, 0, length);
            offset += length;
            return RtcValue.Of(data);
        }

        private static byte ReadUInt8(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            RequireRemaining(endOffset, ref offset, 1);
            byte value = buffer[offset];
            offset++;
            return value;
        }

        private static ushort ReadUInt16BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            RequireRemaining(endOffset, ref offset, 2);
            ushort value = (ushort)((buffer[offset] << 8) | buffer[offset + 1]);
            offset += 2;
            return value;
        }

        private static uint ReadUInt32BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            RequireRemaining(endOffset, ref offset, 4);
            uint value = ((uint)buffer[offset] << 24)
                | ((uint)buffer[offset + 1] << 16)
                | ((uint)buffer[offset + 2] << 8)
                | buffer[offset + 3];
            offset += 4;
            return value;
        }

        private static ulong ReadUInt64BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            RequireRemaining(endOffset, ref offset, 8);
            ulong value = ((ulong)buffer[offset] << 56)
                | ((ulong)buffer[offset + 1] << 48)
                | ((ulong)buffer[offset + 2] << 40)
                | ((ulong)buffer[offset + 3] << 32)
                | ((ulong)buffer[offset + 4] << 24)
                | ((ulong)buffer[offset + 5] << 16)
                | ((ulong)buffer[offset + 6] << 8)
                | buffer[offset + 7];
            offset += 8;
            return value;
        }

        private static short ReadInt16BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            return unchecked((short)ReadUInt16BE(buffer, endOffset, ref offset));
        }

        private static int ReadInt32BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            return unchecked((int)ReadUInt32BE(buffer, endOffset, ref offset));
        }

        private static long ReadInt64BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            return unchecked((long)ReadUInt64BE(buffer, endOffset, ref offset));
        }

        private static float ReadFloat32BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            uint bits = ReadUInt32BE(buffer, endOffset, ref offset);
            var union = new FloatUnion { UIntValue = bits };
            return union.FloatValue;
        }

        private static double ReadFloat64BE(
            byte[] buffer,
            int endOffset,
            ref int offset)
        {
            ulong bits = ReadUInt64BE(buffer, endOffset, ref offset);
            var union = new DoubleUnion { ULongValue = bits };
            return union.DoubleValue;
        }

        private static void RequireRemaining(
            int endOffset,
            ref int offset,
            int required)
        {
            if (offset < 0
                || offset > endOffset
                || required < 0
                || endOffset - offset < required)
            {
                throw new RtcProtocolException(
                    "MessagePack read exceeds the valid frame boundary.");
            }
        }

        private static void ValidateFieldLength(int length, int available, string kind)
        {
            if (length < 0 || length > RtcTlvProtocolEncoder.MaxPayloadLength)
            {
                throw new RtcProtocolException(
                    kind + " length " + length + " exceeds max "
                    + RtcTlvProtocolEncoder.MaxPayloadLength + ".");
            }

            if (available < 0 || length > available)
            {
                throw new RtcProtocolException(
                    kind + " length " + length + " exceeds remaining "
                    + available + " bytes.");
            }
        }

        [System.Runtime.InteropServices.StructLayout(
            System.Runtime.InteropServices.LayoutKind.Explicit)]
        private struct FloatUnion
        {
            [System.Runtime.InteropServices.FieldOffset(0)] public uint UIntValue;
            [System.Runtime.InteropServices.FieldOffset(0)] public float FloatValue;
        }

        [System.Runtime.InteropServices.StructLayout(
            System.Runtime.InteropServices.LayoutKind.Explicit)]
        private struct DoubleUnion
        {
            [System.Runtime.InteropServices.FieldOffset(0)] public ulong ULongValue;
            [System.Runtime.InteropServices.FieldOffset(0)] public double DoubleValue;
        }
    }
}

