using System;
using System.Buffers;
using System.Text;

namespace RTC.Protocol
{
    // Mutable value-type writer used only as a synchronous encode local.
    // Callers must pass it by ref and must not copy a live instance.
    internal struct RtcByteBufferWriter
    {
        private const int GrowthSlack = 64;
        private const int MaxFrameCapacity =
            RtcTlvProtocolEncoder.MaxPayloadLength + 64 * 1024;
        private readonly ArrayPool<byte> _pool;
        private byte[] _buffer;
        private int _position;
        private bool _detached;

        internal RtcByteBufferWriter(int initialCapacity, ArrayPool<byte> pool)
        {
            if (initialCapacity < 1)
            {
                initialCapacity = 1;
            }

            if (initialCapacity > MaxFrameCapacity)
            {
                throw new ArgumentOutOfRangeException(nameof(initialCapacity));
            }

            if (pool == null)
            {
                throw new ArgumentNullException(nameof(pool));
            }

            _pool = pool;
            _buffer = pool.Rent(initialCapacity);
            RtcPoolDiagnostics.RecordRent(growth: false);
            _position = 0;
            _detached = false;
        }

        internal int WrittenCount
        {
            get { return _position; }
        }

        internal int Capacity
        {
            get { return _buffer == null ? 0 : _buffer.Length; }
        }

        internal void WriteByte(byte value)
        {
            EnsureCapacity(1);
            _buffer[_position++] = value;
        }

        internal void WriteBytes(byte[] source, int offset, int count)
        {
            if (source == null)
            {
                throw new ArgumentNullException(nameof(source));
            }

            if (offset < 0 || count < 0 || offset > source.Length - count)
            {
                throw new ArgumentOutOfRangeException();
            }

            if (count == 0)
            {
                return;
            }

            EnsureCapacity(count);
            Buffer.BlockCopy(source, offset, _buffer, _position, count);
            _position += count;
        }

        internal void WriteUtf8(string value)
        {
            string text = value ?? string.Empty;
            int byteCount = Utf8NoBom.GetByteCount(text);
            WriteUtf8Internal(text, byteCount);
        }

        // Caller must provide the exact UTF-8 byte count computed from the
        // same normalized text and the same Utf8NoBom encoding instance.
        internal void WriteUtf8(string value, int precomputedByteCount)
        {
            if (precomputedByteCount < 0)
            {
                throw new ArgumentOutOfRangeException(nameof(precomputedByteCount));
            }

            WriteUtf8Internal(value ?? string.Empty, precomputedByteCount);
        }

        private void WriteUtf8Internal(string text, int byteCount)
        {
            EnsureCapacity(byteCount);
            int written = Utf8NoBom.GetBytes(text, 0, text.Length, _buffer, _position);
            _position += written;
        }

        internal void PatchInt32LE(int offset, int value)
        {
            if (offset < 0 || offset > _position - 4)
            {
                throw new ArgumentOutOfRangeException(nameof(offset));
            }

            _buffer[offset] = (byte)value;
            _buffer[offset + 1] = (byte)(value >> 8);
            _buffer[offset + 2] = (byte)(value >> 16);
            _buffer[offset + 3] = (byte)(value >> 24);
        }

        internal RtcFrame Detach()
        {
            EnsureUsable();

            RtcFrame frame = new RtcFrame
            {
                Buffer = _buffer,
                Length = _position
            };

            _buffer = null;
            _position = 0;
            _detached = true;
            return frame;
        }

        internal void Dispose()
        {
            if (_detached || _buffer == null)
            {
                return;
            }

            byte[] buffer = _buffer;
            _buffer = null;
            _position = 0;
            _pool.Return(buffer);
            RtcPoolDiagnostics.RecordReturn();
        }

        internal static readonly UTF8Encoding Utf8NoBom = new UTF8Encoding(false);

        private void EnsureCapacity(int additional)
        {
            EnsureUsable();

            if (additional < 0 || additional > int.MaxValue - _position)
            {
                throw new ArgumentOutOfRangeException(nameof(additional));
            }

            int required = _position + additional;
            if (required > MaxFrameCapacity)
            {
                throw new ArgumentException(
                    "RTC frame exceeds the configured maximum capacity.",
                    nameof(additional));
            }

            if (required <= _buffer.Length)
            {
                return;
            }

            int nextCapacity = _buffer.Length;
            while (nextCapacity < required)
            {
                int doubled = nextCapacity > int.MaxValue / 2
                    ? int.MaxValue
                    : nextCapacity * 2;
                nextCapacity = Math.Max(doubled, required);
                if (nextCapacity < 0)
                {
                    throw new InvalidOperationException("RTC frame capacity overflow.");
                }
            }

            int rentCapacity = nextCapacity > MaxFrameCapacity - GrowthSlack
                ? MaxFrameCapacity
                : nextCapacity + GrowthSlack;
            byte[] replacement = _pool.Rent(rentCapacity);
            RtcPoolDiagnostics.RecordRent(growth: true);
            Buffer.BlockCopy(_buffer, 0, replacement, 0, _position);
            _pool.Return(_buffer);
            RtcPoolDiagnostics.RecordReturn();
            _buffer = replacement;
        }

        private void EnsureUsable()
        {
            if (_detached || _buffer == null)
            {
                throw new ObjectDisposedException(nameof(RtcByteBufferWriter));
            }
        }
    }
}

