using RTC.Api;

namespace RTC.Protocol
{
    internal readonly struct RtcTlvFrame
    {
        internal RtcTlvFrame(
            byte[] buffer,
            int frameLength,
            uint sequence,
            RtcTlvMetadata metadata,
            string uri,
            int payloadOffset,
            int payloadLength)
        {
            Buffer = buffer;
            FrameLength = frameLength;
            Sequence = sequence;
            Metadata = metadata;
            Uri = uri;
            PayloadOffset = payloadOffset;
            PayloadLength = payloadLength;
        }

        internal byte[] Buffer { get; }
        internal int FrameLength { get; }
        internal uint Sequence { get; }
        internal RtcTlvMetadata Metadata { get; }
        internal string Uri { get; }
        internal int PayloadOffset { get; }
        internal int PayloadLength { get; }
    }

    internal readonly struct RtcTlvDecodedMessage
    {
        internal RtcTlvDecodedMessage(
            uint sequence,
            RtcTlvMetadata metadata,
            string uri,
            RtcValue payload)
        {
            Sequence = sequence;
            Metadata = metadata;
            Uri = uri;
            Payload = payload;
        }

        internal uint Sequence { get; }
        internal RtcTlvMetadata Metadata { get; }
        internal string Uri { get; }
        internal RtcValue Payload { get; }
    }
}

