using System;
using System.Buffers;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using RTC.Protocol;

namespace RTC.Transport
{
    // 单连接异步收发实现（docs/rtc-sdk-transport-redesign-plan.md Task 3 §4/§5/§7）。
    // 参考 FPNN TCPConnection 的 SocketAsyncEventArgs 模型，但按 RTC 契约重新实现：
    //   - 每连接一个 receive 链 + 一个 send 在途操作（§4.2.1/4.2.2）；
    //   - 单飞发送：Send 只入队，由 send 状态机逐帧 partial write（§7.1）；
    //   - 同步完成与异步完成统一走同一处理（§5.3），同步完成限递归深度防爆栈（参考 FPNN
    //     MaxRecursionDeepOfSendFunction/ReceiveFunction = 10）；
    //   - 所有关闭原因收敛到 CloseOnce，只发布一次 Closed（§4.2.4）；
    //   - 连接建立带超时（§5.1）：超时后按 ConnectFailed 关闭，防止不可达地址永久挂起
    //     （对齐旧 TcpTransport 的 connectTimeoutMs 语义）。
    //
    // 线程安全：本类自持 _gate；SAEA 完成后在 gate 内更新状态，启动下一个操作。
    internal sealed class RtcAsyncConnection : IRtcConnection, IDisposable
    {
        private const int MaxRecursionDeep = 10;

        public int Epoch { get; }

        // 连接是否已关闭（CloseOnce 已执行）。
        public bool IsClosed => Volatile.Read(ref _closed) != 0;
        internal string ConnectFailureReason => _connectFailureReason;

        public event Action Connected;
        public event Action<RtcReceiveFrame> Received;
        public event Action<RtcCloseReason> Closed;

        private readonly Socket _socket;
        private readonly object _gate = new object();
        private readonly RtcSendQueue _sendQueue;
        private readonly RtcTlvReceiveBuffer _receiveBuffer;
        private readonly SocketAsyncEventArgs _receiveArgs;
        private readonly SocketAsyncEventArgs _sendArgs;
        private readonly string _host;
        private readonly EndPoint _endPoint;
        private readonly int _connectTimeoutMs;
        private string _connectFailureReason;
        private Timer _connectTimeoutTimer;

        private bool _sendInProgress;
        private bool _connectCalled;
        private bool _connectedPublished;
        private int _closed; // 0=未关，1=已关（CAS，只发布一次 Closed）
        private int _receiveRecursion;
        private int _sendRecursion;
        private bool _closeAfterSendRequested; // P0-1：先发完已入队帧再关闭（kickout ACK 场景）。
        private int _receiveActiveOps; // _receiveArgs 正在使用的操作数（发起到 Process 结束），锁内访问
        private int _sendActiveOps;    // _sendArgs 正在使用的操作数（发起到 Process 结束），锁内访问

        public RtcAsyncConnection(
            int epoch,
            string host,
            IPEndPoint endPoint,
            int connectTimeoutMs = 30000,
            int maxQueuedFrames = 1024,
            int maxQueuedBytes = 16 * 1024 * 1024)
        {
            Epoch = epoch;
            _host = host;
            _endPoint = endPoint;
            _connectTimeoutMs = connectTimeoutMs;

            // 按解析出的地址族创建 Socket：兼容 IPv6-only 网络（iOS App Store 审核要求），
            // 避免系统默认 IPv4 导致 IPv6 地址连接失败。
            AddressFamily addressFamily = _endPoint.AddressFamily == AddressFamily.InterNetworkV6
                ? AddressFamily.InterNetworkV6
                : AddressFamily.InterNetwork;
            _socket = new Socket(addressFamily, SocketType.Stream, ProtocolType.Tcp);

            // 3.2：发送队列限制从配置注入（默认帧数 1024、总字节数 16MB，可覆盖）。
            _sendQueue = new RtcSendQueue(maxQueuedFrames, maxQueuedBytes);
            _receiveBuffer = new RtcTlvReceiveBuffer();

            _receiveArgs = new SocketAsyncEventArgs { RemoteEndPoint = _endPoint };
            _receiveArgs.Completed += OnIoCompleted;

            _sendArgs = new SocketAsyncEventArgs { RemoteEndPoint = _endPoint };
            _sendArgs.Completed += OnIoCompleted;
        }

        public void Connect()
        {
            lock (_gate)
            {
                if (_closed != 0 || _connectCalled)
                {
                    return;
                }

                _connectCalled = true;
            }

            // 连接超时守卫：超过阈值仍未建立连接，按 ConnectFailed 关闭，防止不可达地址挂起。
            // P1-3：创建 Timer 后与 _closed 状态原子关联——若创建期间连接已被关闭（其他线程
            // CloseOnce 抢先 Interlocked.Exchange 取出 null），立即释放，不遗留孤儿 Timer。
            if (_connectTimeoutMs > 0)
            {
                var timer = new Timer(_ => OnConnectTimeout(), null, _connectTimeoutMs,
                    System.Threading.Timeout.Infinite);

                lock (_gate)
                {
                    if (_closed != 0)
                    {
                        // 连接已在此窗口关闭：不保存，立即释放，避免遗留 Timer。
                        try
                        {
                            timer.Dispose();
                        }
                        catch
                        {
                            // 释放异常不阻塞流程。
                        }

                        return;
                    }

                    _connectTimeoutTimer = timer;
                }
            }

            TryConnectOrContinue();
        }

        // 入队一帧并尝试驱动发送。返回 false 表示已关闭/已请求发送后关闭/队列满。
        // P1-5：队列满按 SendQueueFull 原因关闭连接（不伪装成 UserClose）。
        public bool Send(ref RtcFrame frame)
        {
            if (!frame.IsValid)
            {
                return false;
            }

            RtcFrame tcpFrame;
            if (frame.HasTcpOuterLength)
            {
                tcpFrame = frame;
                frame.Clear();
            }
            else
            {
                tcpFrame = AddTcpOuterLength(ref frame);
            }
            bool queueFull = false;
            lock (_gate)
            {
                if (_closed != 0 || _closeAfterSendRequested)
                {
                    ReturnFrame(ref tcpFrame);
                    return false;
                }

                if (!_sendQueue.Enqueue(ref tcpFrame))
                {
                    queueFull = true;
                }
            }

            if (queueFull)
            {
                if (tcpFrame.IsValid)
                {
                    ReturnFrame(ref tcpFrame);
                }
                // 锁外按队列溢出原因关闭（契约 §1.3.9：队列溢出统一收敛，关闭原因明确）。
                CloseOnce(RtcCloseReason.SendQueueFull);
                return false;
            }

            TryStartSend();
            return true;
        }

        private static RtcFrame AddTcpOuterLength(ref RtcFrame frame)
        {
            int totalLength = checked(frame.Length + 4);
            byte[] buffer = ArrayPool<byte>.Shared.Rent(totalLength);
            RtcPoolDiagnostics.RecordRent(growth: false);
            buffer[0] = (byte)frame.Length;
            buffer[1] = (byte)(frame.Length >> 8);
            buffer[2] = (byte)(frame.Length >> 16);
            buffer[3] = (byte)(frame.Length >> 24);
            Buffer.BlockCopy(frame.Buffer, 0, buffer, 4, frame.Length);
            ArrayPool<byte>.Shared.Return(frame.Buffer);
            RtcPoolDiagnostics.RecordReturn();
            frame.Clear();
            return new RtcFrame { Buffer = buffer, Length = totalLength };
        }

        private static void ReturnFrame(ref RtcFrame frame)
        {
            if (!frame.IsValid)
            {
                return;
            }

            ArrayPool<byte>.Shared.Return(frame.Buffer);
            RtcPoolDiagnostics.RecordReturn();
            frame.Clear();
        }

        // 兼容旧的 byte[] 调用者。生产热路径应直接使用 Send(ref RtcFrame)。
        public bool Send(byte[] frame)
        {
            if (frame == null || frame.Length == 0)
            {
                return false;
            }

            byte[] rented = ArrayPool<byte>.Shared.Rent(frame.Length);
            Array.Copy(frame, 0, rented, 0, frame.Length);
            RtcFrame owned = new RtcFrame
            {
                Buffer = rented,
                Length = frame.Length
            };

            bool accepted = Send(ref owned);
            if (!accepted && owned.IsValid)
            {
                ArrayPool<byte>.Shared.Return(owned.Buffer);
                RtcPoolDiagnostics.RecordReturn();
                owned.Clear();
            }

            return accepted;
        }

        // P0-1：先发完已入队的帧（如 kickout ACK），再关闭连接。
        // 调用后禁止新的业务 Send；send 状态机在队列清空后触发实际关闭。
        // 若没有待发帧或发送无法继续，立即关闭。
        public void CloseAfterSend()
        {
            lock (_gate)
            {
                if (_closed != 0 || _closeAfterSendRequested)
                {
                    return;
                }

                _closeAfterSendRequested = true;
            }

            TryStartSend();
            TryCloseAfterSendIfIdle();
        }

        // 队列已空（或连接未建立无帧可发）时立即执行关闭。
        private void TryCloseAfterSendIfIdle()
        {
            bool shouldClose = false;
            lock (_gate)
            {
                if (_closed != 0 || !_closeAfterSendRequested)
                {
                    return;
                }

                // 连接未建立（无帧可发）或队列空且无发送在途 → 立即关闭。
                if (!_connectedPublished || (!_sendInProgress && !_sendQueue.HasPending))
                {
                    shouldClose = true;
                }
            }

            if (shouldClose)
            {
                CloseAfterSendImpl();
            }
        }

        // 实际执行关闭（队列已空，CloseOnce 的 Clear 无害）。只发一次 Closed。
        private void CloseAfterSendImpl()
        {
            CloseOnce(RtcCloseReason.UserClose);
        }

        public void Disconnect()
        {
            // 主动终止连接：统一走关闭收敛，只发一次 Closed。
            CloseOnce(RtcCloseReason.UserDisconnect);
        }

        public void Replace()
        {
            CloseOnce(RtcCloseReason.ConnectCancelled);
        }

        public void Dispose()
        {
            CloseOnce(RtcCloseReason.UserClose);
        }

        // 连接超时触发：仍处于连接建立中 → 按 ConnectFailed 关闭（对齐 connectTimeoutMs 语义）。
        private void OnConnectTimeout()
        {
            CloseOnce(RtcCloseReason.ConnectFailed, "connect_timeout");
        }

        //----------------[ Connect ]-----------------------//

        private void TryConnectOrContinue()
        {
            bool pending = false;
            bool failed = false;
            string failureReason = null;
            lock (_gate)
            {
                if (_closed != 0)
                {
                    return;
                }

                _receiveArgs.RemoteEndPoint = _endPoint;
                try
                {
                    pending = _socket.ConnectAsync(_receiveArgs);
                    _receiveActiveOps++; // 发起成功（异步 pending 或同步完成，随后 Process 访问 SAEA）
                }
                catch (ObjectDisposedException)
                {
                    failureReason = "object_disposed";
                    failed = true;
                }
                catch (SocketException ex)
                {
                    failureReason = "socket_exception:" + ex.SocketErrorCode;
                    failed = true;
                }
                catch (InvalidOperationException)
                {
                    failureReason = "invalid_operation";
                    failed = true;
                }
            }

            if (failed)
            {
                CloseOnce(
                    RtcCloseReason.ConnectFailed,
                    failureReason ?? "connect_failed");
                return;
            }

            if (!pending)
            {
                // 同步完成路径（§5.3）。
                ProcessConnectCompleted(_receiveArgs);
            }
        }

        private void ProcessConnectCompleted(SocketAsyncEventArgs e)
        {
            try
            {
                // 连接完成（成功或失败）即取消超时守卫。
                StopConnectTimeoutTimer();

                if (e.SocketError != SocketError.Success)
                {
                    // 连接建立失败：按 ConnectFailed 处理（契约 §1.4：对应 ConnectFailed 回调，
                    // 不一定发 Closed）。由 Transport 路由到 onConnectFailed。
                    CloseOnce(
                        RtcCloseReason.ConnectFailed,
                        "socket_error:" + e.SocketError);
                    return;
                }

                lock (_gate)
                {
                    if (_closed != 0)
                    {
                        return;
                    }

                    // 发布 Connected（只在当前连接有效时由 Transport 订阅转发）。
                    _connectedPublished = true;
                }

                SafeRaiseConnected();

                // 连接建立后开始接收 + 清空在连接期间入队的帧。
                TryStartReceive();
                TryStartSend();
            }
            finally
            {
                CompleteReceiveOp();
            }
        }

        //----------------[ Receive ]-----------------------//

        private void TryStartReceive()
        {
            bool shouldClose = false;
            lock (_gate)
            {
                if (_closed != 0)
                {
                    return;
                }

                _receiveBuffer.GetReceiveTarget(out byte[] buffer, out int offset, out int length);
                _receiveArgs.SetBuffer(buffer, offset, length);

                try
                {
                    if (_socket.ReceiveAsync(_receiveArgs))
                    {
                        _receiveActiveOps++;
                        return; // 异步完成，等 OnIoCompleted。
                    }

                    _receiveActiveOps++; // 同步完成，锁外 Process 仍在使用 SAEA。
                }
                catch (ObjectDisposedException)
                {
                    shouldClose = true;
                }
                catch (SocketException)
                {
                    shouldClose = true;
                }
                catch (InvalidOperationException)
                {
                    shouldClose = true;
                }
            }

            if (shouldClose)
            {
                CloseOnce(RtcCloseReason.SocketError);
                return;
            }

            // 同步完成路径：限递归深度，超限转线程池，防爆栈。
            _receiveRecursion++;
            if (_receiveRecursion <= MaxRecursionDeep)
            {
                ProcessReceiveCompleted(_receiveArgs);
            }
            else
            {
                _receiveRecursion = 0;
                ThreadPool.QueueUserWorkItem(_ => ProcessReceiveCompleted(_receiveArgs));
            }
        }

        private void ProcessReceiveCompleted(SocketAsyncEventArgs e)
        {
            try
            {
                if (e.SocketError != SocketError.Success)
                {
                    CloseOnce(RtcCloseReason.SocketError);
                    return;
                }

                if (e.BytesTransferred == 0)
                {
                    CloseOnce(RtcCloseReason.RemoteEof);
                    return;
                }

                bool frameReady;
                bool framingError = false;
                lock (_gate)
                {
                    if (_closed != 0)
                    {
                        return;
                    }

                    try
                    {
                        frameReady = _receiveBuffer.OnReceived(e.BytesTransferred);
                    }
                    catch (RTC.Protocol.RtcProtocolException)
                    {
                        // framing 错误（magic/长度/UTF-8 校验失败）：关闭当前连接（契约 §2）。
                        // 不能静默丢弃继续读脏流。
                        frameReady = false;
                        framingError = true;
                    }
                }

                if (framingError)
                {
                    CloseOnce(RtcCloseReason.FramingError);
                    return;
                }

                if (frameReady)
                {
                    RtcReceiveFrame frame;
                    lock (_gate)
                    {
                        frame = _receiveBuffer.TakeFrame();
                    }

                    if (frame.IsValid)
                    {
                        SafeRaiseReceived(frame);
                    }
                }

                TryStartReceive();
            }
            finally
            {
                CompleteReceiveOp();
            }
        }

        //----------------[ Send ]-----------------------//

        private void TryStartSend()
        {
            bool shouldClose = false;
            lock (_gate)
            {
                if (_closed != 0 || _sendInProgress || !_connectedPublished)
                {
                    return; // 已关 / 已在发 / 未连上（入队即可，连上后再发）。
                }

                if (!_sendQueue.TryGetCurrentSegment(
                    out byte[] sendBuffer,
                    out int sendOffset,
                    out int sendCount))
                {
                    // P0-1：请求发送后关闭，且无帧待发 → 立即关闭。
                    return;
                }

                _sendInProgress = true;
                _sendArgs.SetBuffer(sendBuffer, sendOffset, sendCount);

                try
                {
                    if (_socket.SendAsync(_sendArgs))
                    {
                        _sendActiveOps++;
                        return; // 异步完成，等 OnIoCompleted。
                    }

                    _sendActiveOps++; // 同步完成，锁外 Process 仍在使用 SAEA。
                }
                catch (ObjectDisposedException)
                {
                    shouldClose = true;
                }
                catch (SocketException)
                {
                    shouldClose = true;
                }
                catch (InvalidOperationException)
                {
                    shouldClose = true;
                }
            }

            if (shouldClose)
            {
                CloseOnce(RtcCloseReason.SocketError);
                return;
            }

            // 同步完成路径。
            _sendRecursion++;
            if (_sendRecursion <= MaxRecursionDeep)
            {
                ProcessSendCompleted(_sendArgs);
            }
            else
            {
                _sendRecursion = 0;
                ThreadPool.QueueUserWorkItem(_ => ProcessSendCompleted(_sendArgs));
            }
        }

        private void ProcessSendCompleted(SocketAsyncEventArgs e)
        {
            try
            {
                if (e.SocketError != SocketError.Success)
                {
                    CloseOnce(RtcCloseReason.SocketError);
                    return;
                }

                if (e.BytesTransferred <= 0)
                {
                    CloseOnce(RtcCloseReason.SocketError);
                    return;
                }

                lock (_gate)
                {
                    if (_closed != 0)
                    {
                        return;
                    }

                    // 计入已发字节；当前帧完成则消费队列下一帧，否则继续 partial write。
                    _sendQueue.OnSent(e.BytesTransferred);
                    _sendInProgress = false;
                }

                TryCloseAfterSendIfIdle();
                if (_closed != 0)
                {
                    return;
                }

                TryStartSend();
            }
            finally
            {
                CompleteSendOp();
            }
        }

        //----------------[ Close ]-----------------------//

        // 统一关闭收敛：所有关闭原因（EOF/SocketError/FramingError/UserClose/Disconnect/
        // ConnectCancelled）都进入这里，只发布一次 Closed。关闭后阻止新 Send/Receive。
        private void CloseOnce(
            RtcCloseReason reason,
            string connectFailureReason = null)
        {
            if (Interlocked.CompareExchange(ref _closed, 1, 0) != 0)
            {
                return; // 已关闭，只发一次。
            }

            if (reason == RtcCloseReason.ConnectFailed)
            {
                _connectFailureReason = connectFailureReason ?? "connect_failed";
            }

            StopConnectTimeoutTimer();

            bool disposeReceive;
            bool disposeSend;
            lock (_gate)
            {
                // 当前 SAEA 发送仍可能读取 current frame。只清理尚未取出的队列帧，
                // current frame 延迟到 CompleteSendOp 确认无活跃 send 后再归还。
                if (_sendActiveOps > 0)
                {
                    _sendQueue.ClearQueued();
                }
                else
                {
                    _sendQueue.Clear();
                }

                try
                {
                    _socket.Close();
                }
                catch
                {
                    // 关闭 socket 的异常不再上抛。
                }

                // 无活跃操作的 SAEA 立即 Dispose；有活跃操作的等其在 Process* 的 finally 里
                // Dispose（Socket.Close() 只让 in-flight 操作异步失败，此时立即 Dispose 会与
                // 迟到的 Completed 回调 / 同步完成路径的 Process* 竞争访问 SAEA）。
                if (_receiveActiveOps == 0)
                {
                    _receiveBuffer.Reset();
                }

                disposeReceive = _receiveActiveOps == 0;
                disposeSend = _sendActiveOps == 0;
            }

            if (disposeReceive)
            {
                DisposeSaea(_receiveArgs);
            }

            if (disposeSend)
            {
                DisposeSaea(_sendArgs);
            }

            SafeRaiseClosed(reason);
        }

        private static void DisposeSaea(SocketAsyncEventArgs args)
        {
            try
            {
                args.Dispose();
            }
            catch
            {
                // SAEA 释放异常不阻塞关闭收敛。
            }
        }

        // 锁外调用：结束一个 receive/send 侧操作（计数减一）。若连接已关闭且无残留操作，
        // 锁外 Dispose 对应 SAEA（此时该 SAEA 已无任何代码在使用，Dispose 安全）。
        private void CompleteReceiveOp()
        {
            bool dispose;
            lock (_gate)
            {
                _receiveActiveOps--;
                if (_receiveActiveOps == 0 && _closed != 0)
                {
                    _receiveBuffer.Reset();
                }
                dispose = _receiveActiveOps == 0 && _closed != 0;
            }

            if (dispose)
            {
                DisposeSaea(_receiveArgs);
            }
        }

        private void CompleteSendOp()
        {
            bool dispose;
            lock (_gate)
            {
                _sendActiveOps--;
                if (_sendActiveOps == 0 && _closed != 0)
                {
                    _sendQueue.Clear();
                }
                dispose = _sendActiveOps == 0 && _closed != 0;
            }

            if (dispose)
            {
                DisposeSaea(_sendArgs);
            }
        }

        private void StopConnectTimeoutTimer()
        {
            Timer timer = Interlocked.Exchange(ref _connectTimeoutTimer, null);
            if (timer != null)
            {
                try
                {
                    timer.Dispose();
                }
                catch
                {
                    // 定时器释放异常不阻塞流程。
                }
            }
        }

        //----------------[ IO 完成回调 ]-----------------------//

        private void OnIoCompleted(object sender, SocketAsyncEventArgs e)
        {
            switch (e.LastOperation)
            {
                case SocketAsyncOperation.Connect:
                    ProcessConnectCompleted(e);
                    break;
                case SocketAsyncOperation.Receive:
                    ProcessReceiveCompleted(e);
                    break;
                case SocketAsyncOperation.Send:
                    ProcessSendCompleted(e);
                    break;
            }
        }

        //----------------[ Safe events ]-----------------------//

        private void SafeRaiseConnected()
        {
            try
            {
                Connected?.Invoke();
            }
            catch
            {
                // 外部事件异常隔离（契约 §4.2：不打断连接收尾）。
            }
        }

        private void SafeRaiseReceived(RtcReceiveFrame frame)
        {
            if (Received == null)
            {
                ArrayPool<byte>.Shared.Return(frame.Buffer);
                RtcPoolDiagnostics.RecordReceiveReturn();
                return;
            }

            try
            {
                Received?.Invoke(frame);
            }
            catch
            {
                // 订阅者（Transport→Runtime）抛异常不能破坏接收链。
            }
        }

        private void SafeRaiseClosed(RtcCloseReason reason)
        {
            try
            {
                Closed?.Invoke(reason);
            }
            catch
            {
                // Closed 订阅者抛异常不能破坏关闭收尾。
            }
        }
    }
}

