using System;
using System.Buffers;
using RTC.Protocol;

namespace RTC.Transport
{
    // Incrementally assembles TCP's uint32LE outer length plus one complete TLV frame.
    // The outer header and TLV body are intentionally kept in one pooled frame so
    // the send/receive event contract remains one frame per callback.
    internal sealed class RtcTlvReceiveBuffer
    {
        private const int OuterHeaderLength = 4;
        private readonly byte[] _outerHeader = new byte[OuterHeaderLength];
        private int _outerOffset;
        private byte[] _frame;
        private int _frameLength;
        private int _frameOffset;

        public void GetReceiveTarget(out byte[] buffer, out int offset, out int length)
        {
            if (_outerOffset < OuterHeaderLength)
            {
                buffer = _outerHeader;
                offset = _outerOffset;
                length = OuterHeaderLength - _outerOffset;
                return;
            }

            buffer = _frame;
            offset = _frameOffset;
            length = _frameLength - _frameOffset;
        }

        public bool OnReceived(int bytesTransferred)
        {
            if (bytesTransferred <= 0)
            {
                throw new ArgumentOutOfRangeException(nameof(bytesTransferred));
            }

            if (_outerOffset < OuterHeaderLength)
            {
                _outerOffset += bytesTransferred;
                if (_outerOffset < OuterHeaderLength)
                {
                    return false;
                }

                uint length = (uint)(_outerHeader[0]
                    | (_outerHeader[1] << 8)
                    | (_outerHeader[2] << 16)
                    | (_outerHeader[3] << 24));
                if (length < 14 || length > RtcTlvProtocolEncoder.MaxFrameLength)
                {
                    throw new RtcProtocolException("Invalid TCP TLV outer frame length.");
                }

                _frameLength = checked((int)length);
                _frame = ArrayPool<byte>.Shared.Rent(_frameLength);
                RtcPoolDiagnostics.RecordReceiveRent(_frame.Length, _frameLength);
                _frameOffset = 0;
                return false;
            }

            if (_frame == null || bytesTransferred > _frameLength - _frameOffset)
            {
                throw new RtcProtocolException("TCP TLV body exceeds its declared length.");
            }

            _frameOffset += bytesTransferred;
            return _frameOffset == _frameLength;
        }

        internal RtcReceiveFrame TakeFrame()
        {
            RtcReceiveFrame result = new RtcReceiveFrame
            {
                Buffer = _frame,
                Length = _frameLength
            };

            _frame = null;
            _frameLength = 0;
            _frameOffset = 0;
            _outerOffset = 0;
            return result;
        }

        public void Reset()
        {
            if (_frame != null)
            {
                ArrayPool<byte>.Shared.Return(_frame);
                RtcPoolDiagnostics.RecordReceiveReturn();
            }

            _frame = null;
            _frameLength = 0;
            _frameOffset = 0;
            _outerOffset = 0;
        }
    }
}

