namespace RTC.Api
{
    public sealed class RtcRequest
    {
        public RtcRequest(string method, RtcValue payload, string idempotencyKey = null, int timeoutMs = 0)
        {
            Method = method;
            Payload = payload;
            IdempotencyKey = idempotencyKey;
            TimeoutMs = timeoutMs;
        }

        // Runtime 接受请求时生成，调用方不能自行指定或复用。
        public long RequestId { get; internal set; }
        public string Method { get; }
        public RtcValue Payload { get; }
        public string IdempotencyKey { get; }
        public int TimeoutMs { get; }

    }
}

