using System.Text;

namespace RTC.Protocol
{
    // Minimal metadata model for the Gate RTC TLV profile.
    // Empty metadata is valid for compatibility; canonical metadata uses
    // key "mt" and one ASCII byte value: "0", "1", or "2".
    internal readonly struct RtcTlvMetadata
    {
        private const string MessageTypeKey = "mt";
        private static readonly byte[] MessageTypeKeyBytes =
            Encoding.ASCII.GetBytes(MessageTypeKey);
        private static readonly byte[] MessageTypeValueBytes =
        {
            (byte)'0',
            (byte)'1',
            (byte)'2'
        };
        internal RtcTlvMetadata(bool hasMessageType, RtcTlvMessageType messageType)
        {
            HasMessageType = hasMessageType;
            MessageType = messageType;
        }

        internal bool HasMessageType { get; }
        internal RtcTlvMessageType MessageType { get; }

        internal static int GetEncodedLength()
        {
            return 2 + MessageTypeKey.Length + 2 + 1;
        }

        internal static void Write(ref RtcByteBufferWriter writer, RtcTlvMessageType messageType)
        {
            byte[] key = MessageTypeKeyBytes;
            writer.WriteByte((byte)key.Length);
            writer.WriteByte(0);
            writer.WriteBytes(key, 0, key.Length);
            writer.WriteByte(1);
            writer.WriteByte(0);
            byte messageTypeValue = (byte)messageType;
            if (messageTypeValue >= MessageTypeValueBytes.Length)
            {
                throw new RtcProtocolException("Unknown TLV message type.");
            }

            writer.WriteByte(MessageTypeValueBytes[messageTypeValue]);
        }

        internal static RtcTlvMetadata Read(
            byte[] buffer,
            ref int offset,
            int endOffset)
        {
            if (buffer == null || offset < 0 || endOffset < offset || endOffset > buffer.Length)
            {
                throw new RtcProtocolException("Invalid TLV metadata bounds.");
            }

            if (offset == endOffset)
            {
                return new RtcTlvMetadata(false, default(RtcTlvMessageType));
            }

            bool found = false;
            RtcTlvMessageType messageType = default(RtcTlvMessageType);
            while (offset < endOffset)
            {
                int keyLength = ReadLength(buffer, ref offset, endOffset);
                bool isMessageType = keyLength == MessageTypeKeyBytes.Length
                    && MatchesAscii(buffer, offset, MessageTypeKeyBytes);
                SkipBytes(buffer, ref offset, endOffset, keyLength);

                int valueLength = ReadLength(buffer, ref offset, endOffset);
                if (!isMessageType)
                {
                    throw new RtcProtocolException("Unknown TLV metadata key.");
                }

                if (found)
                {
                    throw new RtcProtocolException("Duplicate TLV mt metadata.");
                }

                messageType = ParseMessageType(buffer, offset, valueLength, endOffset);
                SkipBytes(buffer, ref offset, endOffset, valueLength);
                found = true;
            }

            return new RtcTlvMetadata(found, messageType);
        }

        private static RtcTlvMessageType ParseMessageType(
            byte[] buffer,
            int offset,
            int length,
            int endOffset)
        {
            if (length <= 0)
            {
                throw new RtcProtocolException("TLV mt metadata is empty.");
            }

            if (length != 1)
            {
                throw new RtcProtocolException("TLV mt metadata must contain one ASCII byte.");
            }

            if (offset < 0 || offset > endOffset - length)
            {
                throw new RtcProtocolException("TLV mt metadata value exceeds its boundary.");
            }

            byte raw = buffer[offset];
            if (raw >= (byte)'0' && raw <= (byte)'2')
            {
                return (RtcTlvMessageType)(raw - (byte)'0');
            }

            throw new RtcProtocolException("Unknown TLV mt metadata value.");
        }

        private static int ReadLength(byte[] buffer, ref int offset, int endOffset)
        {
            if (endOffset - offset < 2)
            {
                throw new RtcProtocolException("TLV metadata length is truncated.");
            }

            int length = buffer[offset] | (buffer[offset + 1] << 8);
            offset += 2;
            return length;
        }

        private static void SkipBytes(
            byte[] buffer,
            ref int offset,
            int endOffset,
            int length)
        {
            if (length < 0 || endOffset - offset < length)
            {
                throw new RtcProtocolException("TLV metadata entry exceeds its boundary.");
            }

            offset += length;
        }

        private static bool MatchesAscii(
            byte[] buffer,
            int offset,
            byte[] expected)
        {
            if (offset < 0 || expected.Length > buffer.Length - offset)
            {
                return false;
            }

            for (int i = 0; i < expected.Length; i++)
            {
                if (buffer[offset + i] != expected[i])
                {
                    return false;
                }
            }

            return true;
        }
    }
}

