using System;
using System.Buffers;
using System.Collections.Generic;
using System.Threading;
using RTC.Api;
using RTC.Decode;
using RTC.Protocol;
using RTC.Transport;

namespace RTC.Core
{

    // 请求跨重连的隔离靠两件事，都不依赖协议字节本身携带任何“generation”信息（真实
    // FPNN 协议里没有这个字段）：断线时立刻清空 _pendingRequests 并把所有挂起请求判定为
    // TransportLost；RequestId 是 Runtime 生命周期内单调递增的计数器，不会在重连后重置或
    // 撞号。这两点组合起来就足够防止旧连接的迟到 Answer 污染新请求。
    internal sealed partial class RtcRuntime :
        IRtcRuntime,
        IRtcClientDecodeRuntime,
        IRtcRuntimeRequestCompletion,
        IRtcRuntimeTypedRequestCompletion,
        IRtcRuntimeLoginCompletion,
        IRtcRuntimeLoginIdentity,
        IRtcRuntimeClientTelemetry,
        IRtcRuntimeReconnectLifecycle
    {
        private const long DefaultTimeoutMs = 30000;
        private const long HeartbeatPingIntervalMs = 15000;
        private const int DefaultReconnectMaxIntervalSeconds = 8;
        private const int DefaultReconnectLinearCount = 4;
        private const int DefaultReconnectMaxAttempts = 15;
        private const long DefaultReconnectTriggerCooldownMs = 5000;
        private const int MaxReliablePushDedupEntries = 4096;
        private const long ReliablePushDedupWindowMs = 20 * 60 * 1000L;

        // 心跳巡检间隔：比阈值小得多即可及时发现超时，不需要对齐 RTM 的每秒巡检那么频繁
        // （旧代码 RTMControlCenter.cs 是每秒检查一次，新实现没有那么多客户端要巡检，
        // 2 秒一次足够，且仍可控制资源开销）。
        private static readonly TimeSpan HeartbeatCheckInterval = TimeSpan.FromSeconds(2);

        private readonly object _gate = new object();
        private readonly ITransport _transport;
        private readonly IClock _clock;
        private readonly IMonotonicClock _monotonicClock;
        private readonly ITimerScheduler _timerScheduler;
        private readonly int _heartbeatRequestTimeoutMs;
        private readonly RtcRequest _heartbeatRequest;
        private readonly long _requestTimeoutMs;
        private readonly int _reconnectMaxIntervalSeconds;
        private readonly int _reconnectLinearCount;
        private readonly int _maxReconnectAttempts;
        private readonly RtcSdkTracingCollector _tracing;
        private readonly RtcLogger _logger;
        private int _disposed;
        private readonly Dictionary<long, RtcRequestHandle<RtcResponse>> _pendingRequests =
            new Dictionary<long, RtcRequestHandle<RtcResponse>>();
        private readonly Dictionary<long, string> _pendingRequestUris =
            new Dictionary<long, string>();
        private readonly ReliablePushDedupCache _reliablePushDedupCache =
            new ReliablePushDedupCache(
                MaxReliablePushDedupEntries,
                ReliablePushDedupWindowMs);
        private sealed class TypedRequestInfo
        {
            internal TypedRequestInfo(
                RtcResponseDecodePlan plan,
                string expectedUri,
                Action<RtcDecodedResponseResult> callback,
                Action<RtcDecodedResponseResult> completion)
            {
                Plan = plan;
                ExpectedUri = expectedUri;
                Callback = callback;
                Completion = completion;
            }

            internal RtcResponseDecodePlan Plan;
            internal string ExpectedUri;
            internal Action<RtcDecodedResponseResult> Callback;
            internal Action<RtcDecodedResponseResult> Completion;
        }

        private readonly Dictionary<long, TypedRequestInfo> _typedRequests =
            new Dictionary<long, TypedRequestInfo>();
        private readonly Dictionary<long, RequestTraceInfo> _requestTraceInfo =
            new Dictionary<long, RequestTraceInfo>();
        private long _sessionCancelledRequestCount;

        private RtcRuntimeState _state = RtcRuntimeState.Created;
        private long _stateTransitionVersion;
        private Action<RtcResult<RtcLoginResult>> _pendingLoginCallbacks;
        private Action<RtcResult<RtcLoginResult>> _pendingLoginCompletions;
        private enum PushRouteKind
        {
            Generic,
            Typed,
            Mixed
        }

        private sealed class PushRoute
        {
            internal PushRouteKind Kind;
            internal Action<RtcPushEnvelope> GenericHandler;
            internal Action<RtcDecodedPushMessage> TypedHandler;
        }

        private readonly Dictionary<string, PushRoute> _pushRoutes =
            new Dictionary<string, PushRoute>();
        private Action<string, RtcDecodedPushMessage> _pushObserver;
        private RtcLoginConfig _lastLoginConfig;
        private long _nextRequestId;
        private long _nextLoginAttemptId;
        private long _loginAttemptId;
        private int _generation;
        private int _reconnectAttempt;
        private int _lastReconnectErrorCode;
        private long _lastReconnectTriggerAtMs = long.MinValue;
        private int _currentTransportEpoch; // 3.7：当前连接的 transport epoch，校验 Closed 来源。
        private int _heartbeatGeneration; // 8.12.10：心跳 generation，防多 timer 链
        private TimerEntry _heartbeatEntry;
        private bool _heartbeatRequestInFlight;
        private long _heartbeatRequestSentAtMs;
        private long _nextHeartbeatAtMs;
        private TimerEntry _reconnectEntry;
        private long _reconnectAuthAttemptSequence; // never reset between retries
        private ReconnectAuthAttempt _reconnectAuthAttempt; // guarded by _gate

        private enum ReconnectAuthFinishResult
        {
            NoActiveAttempt,
            AlreadyFinalized,
            Finalized
        }

        // Response ownership and lifecycle completion are separate: a claimed
        // successful response can still lose to this connection's Closed event.
        private sealed class ReconnectAuthAttempt
        {
            internal ReconnectAuthAttempt(long id, int epoch, string token)
            {
                Id = id;
                Epoch = epoch;
                Token = token;
            }

            internal readonly long Id;
            internal readonly int Epoch;
            internal readonly string Token;
            internal long RequestId;
            internal IRtcRequestHandle Handle;
            internal bool ResultClaimed;
            internal bool Invalidated;
            internal bool LifecycleFinished;
            internal bool AuthSucceeded;
            internal bool StopRetry;
            internal int ErrorCode;
            internal string FailureReason;
        }

        private sealed class ReconnectAuthFailure
        {
            internal ReconnectAuthFailure(
                long requestId, IRtcRequestHandle handle,
                string reason, bool stopRetry, int errorCode)
            {
                RequestId = requestId;
                Handle = handle;
                Reason = reason;
                StopRetry = stopRetry;
                ErrorCode = errorCode;
            }

            internal readonly long RequestId;
            internal readonly IRtcRequestHandle Handle;
            internal readonly string Reason;
            internal readonly bool StopRetry;
            internal readonly int ErrorCode;
        }
        private readonly List<RecoveryLoginWaiter> _recoveryLoginWaiters =
            new List<RecoveryLoginWaiter>(); // guarded by _gate
        private string _sessionId;
        private string _loginTraceId;
        private long _loginStartElapsedMs = -1;
        private bool _sessionEnded;
        private string _reconnectCycleId;
        private string _reconnectTraceId;
        private string _reconnectTrigger;
        private RtcCloseReason? _pendingDisconnectReason;
        private int _pendingDisconnectEpoch;
        private long _reconnectStartElapsedMs = -1;
        private int _reconnectAttemptNumber;
        private Func<int, int, bool> _reloginPolicy;
        private bool _loginResultTracked;
        private long _sessionStartElapsedMs = -1;
        private bool _firstPushReceived;
        private bool _sessionClosedRaised;
        private bool _emptyTlvMetadataMtypeReported;
        private bool _invalidReliablePushReported;
        private volatile bool _clientTelemetryEnabled;

        private sealed class SessionEndContext
        {
            internal SessionEndContext(string transportEpoch, string reconnectCycleId)
            {
                TransportEpoch = transportEpoch;
                ReconnectCycleId = reconnectCycleId;
            }

            internal string TransportEpoch { get; }
            internal string ReconnectCycleId { get; }
        }

        // Reconnecting 期间加入 Login 的等待者：结局发生时由 Detach/Resolve 结束，
        // 或自身超时结束；TryClaim 保证恰好一次回调。
        private sealed class RecoveryLoginWaiter
        {
            internal RecoveryLoginWaiter(
                Action<RtcResult<RtcLoginResult>> callback,
                Action<RtcResult<RtcLoginResult>> completion)
            {
                Callback = callback;
                Completion = completion;
            }

            internal readonly Action<RtcResult<RtcLoginResult>> Callback;
            internal readonly Action<RtcResult<RtcLoginResult>> Completion;
            internal IDisposable TimeoutEntry; // guarded by _gate
            private int _claimed;

            internal bool TryClaim()
            {
                return Interlocked.Exchange(ref _claimed, 1) == 0;
            }

            internal IDisposable ConsumeTimeoutEntry()
            {
                IDisposable entry = TimeoutEntry;
                TimeoutEntry = null;
                return entry;
            }
        }

        internal int PendingRequestTraceCount
        {
            get { lock (_gate) { return _requestTraceInfo.Count; } }
        }

        private sealed class RequestTraceInfo
        {
            internal RequestTraceInfo(
                string method,
                long startElapsedMs,
                int timeoutMs,
                bool isLoginAuth,
                bool isInternalRequest)
            {
                Method = method;
                StartElapsedMs = startElapsedMs;
                TimeoutMs = timeoutMs;
                IsLoginAuth = isLoginAuth;
                IsInternalRequest = isInternalRequest;
            }

            internal string Method { get; }
            internal long StartElapsedMs { get; }
            internal int TimeoutMs { get; }
            internal bool IsLoginAuth { get; }
            internal bool IsInternalRequest { get; }
        }

        private sealed class TimerEntry
        {
            internal readonly int Generation;
            internal IDisposable Subscription;

            internal TimerEntry(int generation)
            {
                Generation = generation;
            }
        }

        private long GetElapsedDurationMs(long startElapsedMs)
        {
            if (startElapsedMs < 0)
            {
                return 0;
            }

            return Math.Max(
                0,
                _monotonicClock.ElapsedMilliseconds - startElapsedMs);
        }

        // 阶段一（8.14.2.4）：业务 callback 异步投递器。IO 线程只解码/更新状态/投递，
        // 慢业务回调不阻塞网络收发。Close 时统一关闭。
        private readonly ICallbackDispatcher _dispatcher;

        // 生命周期事件（阶段 3 P4）：对外暴露状态机变化与 kickout 推送。
        // 与 _pushHandler 不同，事件在 Runtime 关闭后仍保持可订阅（业务层可监听 Close）。
        public event Action<int> SessionClosed;
        public event Action Kickout;
        public event Action<long> KickoutRoom;
        public event Action<int, int> ReloginWillStart;
        public event Action<bool, bool, int, int> ReloginCompleted;
        public event Action<RtcRuntimeState> ClientStatusChanged;
        private event Action<int, int> ReconnectAttemptStarting;
        private event Action<RtcRuntimeState, long> SessionStateTransitioned;

        event Action<int, int> IRtcRuntimeReconnectLifecycle.ReconnectAttemptStarting
        {
            add { ReconnectAttemptStarting += value; }
            remove { ReconnectAttemptStarting -= value; }
        }

        event Action<RtcRuntimeState, long> IRtcRuntimeReconnectLifecycle.SessionStateTransitioned
        {
            add { SessionStateTransitioned += value; }
            remove { SessionStateTransitioned -= value; }
        }

        void IRtcRuntimeReconnectLifecycle.PostLifecycleCallback(Action callback)
        {
            PostCallback(callback);
        }

        public RtcRuntime(ITransport transport, IClock clock, ITimerScheduler timerScheduler, long heartbeatTimeoutMs)
            : this(
                transport,
                clock,
                clock as IMonotonicClock ?? new SystemMonotonicClock(),
                timerScheduler,
                heartbeatTimeoutMs,
                DefaultTimeoutMs,
                DefaultReconnectMaxIntervalSeconds,
                DefaultReconnectLinearCount,
                DefaultReconnectMaxAttempts,
                new RtcCallbackDispatcher(),
                null)
        {
        }

        internal RtcRuntime(
            ITransport transport,
            IClock clock,
            IMonotonicClock monotonicClock,
            ITimerScheduler timerScheduler,
            long heartbeatTimeoutMs,
            ICallbackDispatcher dispatcher)
            : this(
                transport,
                clock,
                monotonicClock,
                timerScheduler,
                heartbeatTimeoutMs,
                DefaultTimeoutMs,
                DefaultReconnectMaxIntervalSeconds,
                DefaultReconnectLinearCount,
                DefaultReconnectMaxAttempts,
                dispatcher,
                null)
        {
        }

        // Allows callers with a controlled dispatcher to preserve callback scheduling semantics.
        internal RtcRuntime(
            ITransport transport,
            IClock clock,
            IMonotonicClock monotonicClock,
            ITimerScheduler timerScheduler,
            long heartbeatTimeoutMs,
            long requestTimeoutMs,
            int reconnectMaxIntervalSeconds,
            int reconnectLinearCount,
            int maxReconnectAttempts,
            ICallbackDispatcher dispatcher,
            RtcSdkTracingCollector tracing,
            RtcLogger logger = null)
        {
            _transport = transport;
            _clock = clock;
            _monotonicClock = monotonicClock ?? new SystemMonotonicClock();
            _timerScheduler = timerScheduler;
            _heartbeatRequestTimeoutMs = heartbeatTimeoutMs > int.MaxValue
                ? int.MaxValue
                : (int)Math.Max(1, heartbeatTimeoutMs);
            _heartbeatRequest = new RtcRequest(
                RtcGateContract.ControlPing,
                RtcValue.EmptyMap,
                timeoutMs: _heartbeatRequestTimeoutMs);
            _requestTimeoutMs = requestTimeoutMs > 0 ? requestTimeoutMs : DefaultTimeoutMs;
            _reconnectMaxIntervalSeconds = reconnectMaxIntervalSeconds > 0
                ? reconnectMaxIntervalSeconds
                : DefaultReconnectMaxIntervalSeconds;
            _reconnectLinearCount = reconnectLinearCount > 0
                ? reconnectLinearCount
                : DefaultReconnectLinearCount;
            _maxReconnectAttempts = maxReconnectAttempts > 0
                ? maxReconnectAttempts
                : DefaultReconnectMaxAttempts;
            _dispatcher = dispatcher;
            _tracing = tracing;
            _logger = logger ?? RtcLogger.Create(null, RtcLogLevel.Off);
            _transport.Received += OnTransportReceived;
            _transport.Closed += OnTransportClosed;
        }

        internal RtcRuntime(
            ITransport transport,
            IClock clock,
            ITimerScheduler timerScheduler,
            long heartbeatTimeoutMs,
            ICallbackDispatcher dispatcher)
            : this(
                transport,
                clock,
                clock as IMonotonicClock ?? new SystemMonotonicClock(),
                timerScheduler,
                heartbeatTimeoutMs,
                DefaultTimeoutMs,
                DefaultReconnectMaxIntervalSeconds,
                DefaultReconnectLinearCount,
                DefaultReconnectMaxAttempts,
                dispatcher,
                null)
        {
        }

        public RtcRuntimeState State
        {
            get { lock (_gate) { return _state; } }
        }

        long IRtcRuntimeLoginIdentity.CurrentLoginUid
        {
            get
            {
                lock (_gate)
                {
                    return _lastLoginConfig == null ? 0 : _lastLoginConfig.Uid;
                }
            }
        }

        // 统一的状态切换入口：更新 _state 并触发 ClientStatusChanged。
        // 只在"调用方未持有 _gate"时使用（内部 lock 释放后才触发 event，保证 event 在锁外）。
        // 若调用点已持有 _gate，改用 ChangeStateLocked + 锁外 SafeRaiseStatusChanged。
        // event 触发用 SafeRaise*（异常隔离，不打断生命周期收尾，见 8.2）。
        private void SetState(
            RtcRuntimeState next,
            string failureReason = null,
            bool pendingLogin = false,
            string closeInitiator = null)
        {
            RtcRuntimeState previous;
            bool changed;
            long transitionVersion = 0;
            lock (_gate)
            {
                previous = _state;
                changed = ChangeState(next);
                if (changed)
                {
                    transitionVersion = RecordStatusTransitionLocked();
                }
            }

            if (changed)
            {
                try
                {
                    _tracing?.TrackConnectionState(
                        _sessionId,
                        _currentTransportEpoch.ToString(),
                        previous.ToString(),
                        next.ToString(),
                        0,
                        null,
                        failureReason,
                        pendingLogin,
                        closeInitiator);
                }
                finally
                {
                    SafeRaiseStatusChanged(next, transitionVersion);
                }
            }
        }

        // 仅当状态仍为 expected 时切换，避免锁外执行的迟到回调覆盖 Close()。
        // 状态事件仍在锁外触发，与 SetState 保持一致。
        private bool TrySetStateFrom(
            RtcRuntimeState expected,
            RtcRuntimeState next,
            string failureReason = null)
        {
            RtcRuntimeState previous;
            bool changed;
            long transitionVersion = 0;
            lock (_gate)
            {
                if (_state != expected)
                {
                    return false;
                }

                previous = _state;
                changed = ChangeState(next);
                if (changed)
                {
                    transitionVersion = RecordStatusTransitionLocked();
                }
            }

            if (changed)
            {
                try
                {
                    _tracing?.TrackConnectionState(
                        _sessionId,
                        _currentTransportEpoch.ToString(),
                        previous.ToString(),
                        next.ToString(),
                        0,
                        null,
                        failureReason);
                }
                finally
                {
                    SafeRaiseStatusChanged(next, transitionVersion);
                }
            }

            return changed;
        }

        private bool TryTransitionInitialLogin(
            RtcRuntimeState next,
            string failureReason,
            out Action<RtcResult<RtcLoginResult>> callbacks,
            out Action<RtcResult<RtcLoginResult>> completions,
            bool? clientTelemetryState = null)
        {
            RtcRuntimeState previous;
            bool changed;
            bool pendingLogin;
            long transitionVersion = 0;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connecting)
                {
                    callbacks = null;
                    completions = null;
                    return false;
                }

                if (next == RtcRuntimeState.Connected
                    && clientTelemetryState.HasValue)
                {
                    _clientTelemetryEnabled = clientTelemetryState.Value;
                    _tracing?.SetClientTelemetryEnabled(
                        clientTelemetryState.Value);
                }

                previous = _state;
                changed = ChangeState(next);
                if (changed)
                {
                    transitionVersion = RecordStatusTransitionLocked();
                }

                callbacks = _pendingLoginCallbacks;
                completions = _pendingLoginCompletions;
                _pendingLoginCallbacks = null;
                _pendingLoginCompletions = null;
                pendingLogin = callbacks != null || completions != null;
            }

            if (changed)
            {
                try
                {
                    _tracing?.TrackConnectionState(
                        _sessionId,
                        _currentTransportEpoch.ToString(),
                        previous.ToString(),
                        next.ToString(),
                        0,
                        null,
                        failureReason,
                        pendingLogin,
                        null);
                }
                finally
                {
                    SafeRaiseStatusChanged(next, transitionVersion);
                }
            }

            return changed;
        }

        // 锁内更新状态（可重入），返回是否发生变化。不触发任何外部 event（8.1）。
        private bool ChangeState(RtcRuntimeState next)
        {
            lock (_gate)
            {
                // Closed 是 Runtime 的终态；迟到的连接/重连回调不得复活它。
                if (_state == RtcRuntimeState.Closed
                    && next != RtcRuntimeState.Closed)
                {
                    return false;
                }

                if (_state == next)
                {
                    return false;
                }

                _state = next;
                return true;
            }
        }

        // 外部事件安全触发：异常隔离，不向外传播（8.2）。
        private void SafeRaise(Action raise)
        {
            try
            {
                raise?.Invoke();
            }
            catch
            {
                // 外部事件属于用户代码，异常只隔离，不中断生命周期收尾。
            }
        }

        // Multicast delegates stop at the first throwing subscriber. Keep the
        // existing exception boundary while isolating each subscriber so one
        // lifecycle or Push handler cannot suppress the following handlers.
        private static bool InvokeEachSubscriber(
            Delegate handlers,
            Action<Delegate> invoke)
        {
            if (handlers == null)
            {
                return false;
            }

            bool failed = false;
            Delegate[] invocationList = handlers.GetInvocationList();
            for (int i = 0; i < invocationList.Length; i++)
            {
                try
                {
                    invoke(invocationList[i]);
                }
                catch
                {
                    failed = true;
                }
            }

            return failed;
        }

        private static IDisposable DetachTimerEntryLocked(ref TimerEntry entry)
        {
            if (entry == null)
            {
                return null;
            }

            IDisposable subscription = entry.Subscription;
            entry = null;
            return subscription;
        }

        private void DisposeSubscription(IDisposable subscription)
        {
            if (subscription == null)
            {
                return;
            }

            try
            {
                subscription.Dispose();
            }
            catch (Exception error)
            {
                _logger.Error("timer subscription dispose", error);
            }
        }

        // 阶段一：把业务 callback 投递到 dispatcher（IO 线程不执行慢业务）。
        // 队列满/已关闭时的降级策略（3.5，契约 §4.2）：
        //   - High（request completion / lifecycle）：必须保住终态——同步回退执行（SafeRaise 隔离）。
        //     此时调用方通常是 IO/timer 线程，同步执行是"保终态优先"的最后手段，
        //     但 dispatcher 满说明负载异常，属异常路径而非常态。
        //   - Normal（push）：丢弃并记录——push 可丢/可重推，绝不让 IO 线程同步执行用户 push handler。
        private void PostCallback(Action callback, RtcCallbackPriority priority = RtcCallbackPriority.High)
        {
            if (callback == null)
            {
                return;
            }

            // 外部 dispatcher 的 Post 可能在 callback 已执行/入队后再抛异常。
            // 用一次性包装保证 High 兜底时不会重复执行业务 callback；
            // Normal 仍保持原语义：投递失败时丢弃，不在 IO 线程同步执行 push。
            int callbackInvoked = 0;
            Action callbackOnce = () =>
            {
                if (Interlocked.Exchange(ref callbackInvoked, 1) != 0)
                {
                    return;
                }

                // 与默认 dispatcher 的 worker 隔离行为一致：业务 callback 异常
                // 不得穿透到 Runtime 的请求完成/关闭链路。
                SafeRaise(callback);
            };

            RtcCallbackPostResult postResult = TryPostCallback(callbackOnce, priority);
            if (postResult == RtcCallbackPostResult.Accepted)
            {
                return;
            }

            if (priority == RtcCallbackPriority.Normal)
            {
                // push 队列满、关闭或 dispatcher 异常：丢弃，不让 IO 线程同步执行用户 handler。
                return;
            }

            // High 队列满/已关闭或 dispatcher 异常：同步回退执行，保证 request/lifecycle
            // 终态不丢；callbackOnce 会防止 dispatcher 已执行/已入队后的重复执行。
            SafeRaise(callbackOnce);
        }





        private void PostLoginCallbacks(
            Action<RtcResult<RtcLoginResult>> callbacks,
            RtcResult<RtcLoginResult> result,
            bool startHeartbeat)
        {
            if (callbacks == null && !startHeartbeat)
            {
                return;
            }

            PostCallback(
                () =>
                {
                    if (startHeartbeat)
                    {
                        StartHeartbeatWatchdog();
                    }

                    DispatchLoginCallbacks(callbacks, result);
                },
                RtcCallbackPriority.High);
        }

        private void DispatchLoginCallbacks(
            Action<RtcResult<RtcLoginResult>> callbacks,
            RtcResult<RtcLoginResult> result)
        {
            if (callbacks == null)
            {
                return;
            }

            Delegate[] invocationList = callbacks.GetInvocationList();
            for (int i = 0; i < invocationList.Length; i++)
            {
                try
                {
                    ((Action<RtcResult<RtcLoginResult>>)invocationList[i])(result);
                }
                catch (Exception error)
                {
                    _logger.Error("login callback", error);
                }
            }
        }

        private void DispatchLoginCompletions(
            Action<RtcResult<RtcLoginResult>> completions,
            RtcResult<RtcLoginResult> result)
        {
            if (completions == null)
            {
                return;
            }

            Delegate[] invocationList = completions.GetInvocationList();
            for (int i = 0; i < invocationList.Length; i++)
            {
                try
                {
                    ((Action<RtcResult<RtcLoginResult>>)invocationList[i])(result);
                }
                catch (Exception error)
                {
                    _logger.Error("login completion", error);
                }
            }
        }

private RtcCallbackPostResult TryPostCallback(
            Action callback,
            RtcCallbackPriority priority)
        {
            if (callback == null)
            {
                return RtcCallbackPostResult.InvalidCallback;
            }

            try
            {
                return _dispatcher.TryPostWithReason(callback, priority);
            }
            catch (Exception error)
            {
                _logger.Error("callback dispatch", error);
                return RtcCallbackPostResult.DispatcherException;
            }
        }

private static string GetCallbackPostFailureReason(
            RtcCallbackPostResult result)
        {
            switch (result)
            {
                case RtcCallbackPostResult.QueueFull:
                    return "queue_full";
                case RtcCallbackPostResult.Closed:
                    return "sdk_closed";
                case RtcCallbackPostResult.DispatcherException:
                    return "dispatcher_exception";
                default:
                    return "invalid_callback";
            }
        }

