        // Version is advanced under _gate at the state transition. Delayed
        // business callbacks only publish the state that is still current.
        private long RecordStatusTransitionLocked()
            => ++_stateTransitionVersion;

        private void SafeRaiseStatusChanged(
            RtcRuntimeState state,
            long version)
        {
            SafeRaise(() => InvokeEachSubscriber(
                SessionStateTransitioned,
                handler => ((Action<RtcRuntimeState, long>)handler)(
                    state,
                    version)));

            PostCallback(() =>
            {
                lock (_gate)
                {
                    if (_stateTransitionVersion != version || _state != state)
                    {
                        return;
                    }
                }

                InvokeEachSubscriber(
                    ClientStatusChanged,
                    handler => ((Action<RtcRuntimeState>)handler)(state));
            }, RtcCallbackPriority.High);
        }
