            lock (_gate)
            {
                shouldRaise = !_sessionClosedRaised;
                if (shouldRaise)
                {
                    _sessionClosedRaised = true;
                }
            }

            if (!shouldRaise)
            {
                return;
            }

            PostCallback(
                () =>
                {
                    InvokeEachSubscriber(
                        Kickout,
                        handler => ((Action)handler)());
                    InvokeEachSubscriber(
                        SessionClosed,
                        handler => ((Action<int>)handler)(errorCode));
                });
        }
