        private void TrackReconnectWillStart(int lastErrorCode, int retriedCount, string reconnectTrigger)
        {
            _reconnectCycleId = Guid.NewGuid().ToString("N");
            _reconnectTraceId = Guid.NewGuid().ToString("N");
            _reconnectTrigger = string.IsNullOrEmpty(reconnectTrigger)
                ? "unknown"
                : reconnectTrigger;
            _reconnectStartElapsedMs = _monotonicClock.ElapsedMilliseconds;
            _reconnectAttemptNumber = 1;
            _tracing?.TrackReconnect(
                _sessionId,
                _reconnectTraceId,
                _reconnectCycleId,
                _reconnectAttemptNumber,
                "will_start",
                false,
                false,
                retriedCount,
                lastErrorCode,
                _reconnectTrigger,
                -1);
        }

        private void TrackReconnectCompleted(
            bool successful,
            bool retryAgain,
            int errorCode,
            int retriedCount,
            string failureReason = null)
        {
            long durationMs = GetElapsedDurationMs(_reconnectStartElapsedMs);
            if (!successful && failureReason == "reconnect_auth_timeout")
            {
                durationMs = _requestTimeoutMs;
            }

            _tracing?.TrackReconnect(
                _sessionId,
                _reconnectTraceId,
                _reconnectCycleId,
                _reconnectAttemptNumber,
                "completed",
                successful,
                retryAgain,
                retriedCount,
                errorCode,
                _reconnectTrigger,
                durationMs,
                failureReason);
            if (retryAgain)
            {
                _reconnectAttemptNumber++;
                _reconnectTraceId = Guid.NewGuid().ToString("N");
            }
        }

        private void SafeRaiseReloginWillStart(int lastErrorCode, int retriedCount, string reconnectTrigger = null)
        {
            TrackReconnectWillStart(lastErrorCode, retriedCount, reconnectTrigger);
            PostCallback(
                () => InvokeEachSubscriber(
                    ReloginWillStart,
                    handler => ((Action<int, int>)handler)(
                        lastErrorCode,
                        retriedCount)));
        }

        private void SafeRaiseReloginCompleted(
            bool successful,
            bool retryAgain,
            int errorCode,
            int retriedCount,
            string failureReason = null)
        {
            TrackReconnectCompleted(
                successful,
                retryAgain,
                errorCode,
                retriedCount,
                failureReason);
            PostCallback(
                () =>
                {
                    if (successful)
                    {
                        // A queued success can outlive Close; discard it at delivery.
                        lock (_gate)
                        {
                            if (_state == RtcRuntimeState.Closed)
                            {
                                return;
                            }
                        }
                    }

                    InvokeEachSubscriber(
                        ReloginCompleted,
                        handler => ((Action<bool, bool, int, int>)handler)(
                            successful,
                            retryAgain,
                            errorCode,
                            retriedCount));
                });
        }

