        private void TrackLoginResultOnce(
            string result,
            int errorCode,
            int remoteErrorCode,
            long durationMs,
            string failureStage,
            string failureReason = null)
        {
            bool shouldTrack;
            lock (_gate)
            {
                shouldTrack = !_loginResultTracked;
                if (shouldTrack)
                {
                    _loginResultTracked = true;
                }
            }

            if (shouldTrack)
            {
                long loginAttemptId;
                bool supersededByNewLogin;
                lock (_gate)
                {
                    loginAttemptId = _loginAttemptId;
                    supersededByNewLogin = loginAttemptId > 0
                        && loginAttemptId < _nextLoginAttemptId;
                }
                _tracing?.TrackLoginResult(
                    _sessionId,
                    _loginTraceId,
                    result,
                    errorCode,
                    remoteErrorCode,
                    Math.Max(0, durationMs),
                    failureStage,
                    failureReason,
                    loginAttemptId,
                    supersededByNewLogin);
            }
        }

        private void TryMarkSessionEnded(
            string endType,
            string closeReason,
            int errorCode,
            bool expected,
            string failureReason = null,
            SessionEndContext sessionEndContext = null)
        {
            bool shouldTrack;
            string sessionId;
            string transportEpoch;
            string reconnectCycleId;
            long durationMs;
            long cancelledCount;
            lock (_gate)
            {
                shouldTrack = !_sessionEnded && !string.IsNullOrEmpty(_sessionId);
                if (!shouldTrack)
                {
                    // Session End 已完成或当前没有有效 session；丢弃迟到的取消计数，
                    // 避免它残留到本次生命周期之后。
                    Interlocked.Exchange(
                        ref _sessionCancelledRequestCount,
                        0);
                    return;
                }

                _sessionEnded = true;
                sessionId = _sessionId;
                transportEpoch = sessionEndContext == null
                    ? _currentTransportEpoch.ToString()
                    : sessionEndContext.TransportEpoch;
                reconnectCycleId = sessionEndContext == null
                    ? _reconnectCycleId
                    : sessionEndContext.ReconnectCycleId;
                durationMs = GetElapsedDurationMs(_sessionStartElapsedMs);
                cancelledCount = Interlocked.Exchange(
                    ref _sessionCancelledRequestCount,
                    0);
            }

            _tracing?.TrackSessionEnd(
                sessionId,
                endType,
                closeReason,
                errorCode,
                expected,
                Math.Max(0, durationMs),
                (int)Math.Min(int.MaxValue, cancelledCount),
                failureReason,
                transportEpoch,
                reconnectCycleId);
        }

        public bool Login(
            RtcLoginConfig config,
            Action<RtcResult<RtcLoginResult>> callback)
        {
            return LoginCore(config, callback, null);
        }

        bool IRtcRuntimeLoginCompletion.Login(
            RtcLoginConfig config,
            Action<RtcResult<RtcLoginResult>> callback,
            Action<RtcResult<RtcLoginResult>> completion)
        {
            return LoginCore(config, callback, completion);
        }

        // Login 契约（与 IRtcRuntime.Login 的 XML 注释保持一致）：
        // - Created：启动登录流程。
        // - Connecting：加入当前登录，随首登结果回调。
        // - Connected：返回一次成功回调（假成功改为：身份不一致时失败回调）。
        // - Reconnecting：加入恢复等待队列，按重连结局恰好回调一次。
        // - ReconnectFailed / Closed：拒绝（返回 false，不回调）。
        // - 活动会话（Connecting/Connected/Reconnecting）中身份不一致：不改会话状态，
        //   返回 true 并回调一次 InvalidArgument 失败。
        private bool LoginCore(
            RtcLoginConfig config,
            Action<RtcResult<RtcLoginResult>> callback,
            Action<RtcResult<RtcLoginResult>> completion)
        {
            bool invalidState = false;
            bool identityMismatch = false;
            bool stateChanged = false;
            bool alreadyConnected = false;
            bool startLogin = false;
            long transitionVersion = 0;
            long loginAttemptId;
            if (config == null)
            {
                return false;
            }

            lock (_gate)
            {
                loginAttemptId = ++_nextLoginAttemptId;
                if (_lastLoginConfig != null)
                {
                    if (_lastLoginConfig.ProjectId == config.ProjectId
                        && _lastLoginConfig.Uid == config.Uid)
                    {
                        // Keep the latest credentials available to a future
                        // reconnect even when this state cannot start a login.
                        if (!string.IsNullOrEmpty(config.Token))
                        {
                            _lastLoginConfig = config;
                        }
                    }
                    else if (_state == RtcRuntimeState.Connecting
                        || _state == RtcRuntimeState.Connected
                        || _state == RtcRuntimeState.Reconnecting)
                    {
                        identityMismatch = true;
                    }
                }

                if (!identityMismatch)
                {
                    if (_state == RtcRuntimeState.Created)
                    {
                        _clientTelemetryEnabled = false;
                        _tracing?.SetClientTelemetryEnabled(false);
                        _sessionId = Guid.NewGuid().ToString("N");
                        _loginTraceId = Guid.NewGuid().ToString("N");
                        _loginAttemptId = loginAttemptId;
                        _loginStartElapsedMs = _monotonicClock.ElapsedMilliseconds;
                        _sessionStartElapsedMs = _loginStartElapsedMs;
                        _sessionEnded = false;
                        _sessionClosedRaised = false;
                        _loginResultTracked = false;
                        _emptyTlvMetadataMtypeReported = false;
                        _invalidReliablePushReported = false;
                        Interlocked.Exchange(ref _sessionCancelledRequestCount, 0);
                        _pendingLoginCallbacks = null;
                        _pendingLoginCompletions = null;
                        if (callback != null)
                        {
                            _pendingLoginCallbacks += callback;
                        }

                        if (completion != null)
                        {
                            _pendingLoginCompletions += completion;
                        }

                        // Persist credentials at flow start so later logins in any
                        // state can refresh the token through the update block at
                        // the top of this method.
                        _lastLoginConfig = config;

                        if (ChangeState(RtcRuntimeState.Connecting))
                        {
                            stateChanged = true;
                            transitionVersion = RecordStatusTransitionLocked();
                        }

                        startLogin = true;
                    }
                    else if (_state == RtcRuntimeState.Connecting)
                    {
                        if (callback != null)
                        {
                            _pendingLoginCallbacks += callback;
                        }

                        if (completion != null)
                        {
                            _pendingLoginCompletions += completion;
                        }
                    }
                    else if (_state == RtcRuntimeState.Connected)
                    {
                        alreadyConnected = true;
                    }
                    else if (_state == RtcRuntimeState.Reconnecting)
                    {
                        // 加入恢复等待队列：按重连结局（成功/耗尽/关闭/超时）恰好回调一次。
                        var waiter = new RecoveryLoginWaiter(callback, completion);
                        if (config.TimeoutMs > 0)
                        {
                            waiter.TimeoutEntry = _timerScheduler.Schedule(
                                TimeSpan.FromMilliseconds(config.TimeoutMs),
                                () => OnRecoveryLoginWaiterTimeout(waiter));
                        }

                        _recoveryLoginWaiters.Add(waiter);
                    }
                    else
                    {
                        invalidState = true;
                    }
                }
            }

            if (identityMismatch)
            {
                _tracing?.TrackLoginResult(
                    _sessionId,
                    Guid.NewGuid().ToString("N"),
                    "failure",
                    (int)RtcErrorCode.InvalidArgument,
                    0,
                    0,
                    "identity_mismatch",
                    "identity_mismatch",
                    loginAttemptId,
                    false);
                RtcResult<RtcLoginResult> mismatchResult = RtcResult<RtcLoginResult>.Failed(
                    0,
                    RtcResultStatus.Failed,
                    new RtcError(
                        RtcErrorCode.InvalidArgument,
                        0,
                        "Login identity does not match the active session.",
                        false));
                // 与 DispatchLoginCompletions 一致隔离同步 completion，
                // 异常不得穿透 Login 调用方，callback 仍需投递。
                try
                {
                    completion?.Invoke(mismatchResult);
                }
                catch (Exception error)
                {
                    _logger.Error("login completion", error);
                }

                PostCallback(() => callback?.Invoke(mismatchResult));
                return true;
            }

            if (invalidState)
            {
                _tracing?.TrackLoginResult(
                    _sessionId,
                    Guid.NewGuid().ToString("N"),
                    "failure",
                    (int)RtcErrorCode.InvalidState,
                    0,
                    0,
                    "invalid_state",
                    "runtime_state_not_loginable",
                    loginAttemptId,
                    false);
                return false;
            }

            if (alreadyConnected)
            {
                var result = RtcResult<RtcLoginResult>.Succeeded(
                    0,
                    new RtcLoginResult
                    {
                        ClientTelemetryEnabled = _clientTelemetryEnabled
                    });
                try
                {
                    completion?.Invoke(result);
                }
                catch (Exception error)
                {
                    _logger.Error("login completion", error);
                }

                PostCallback(
                    () => callback?.Invoke(result));
                return true;
            }

            if (stateChanged)
            {
                try
                {
                    _tracing?.TrackConnectionState(
                        _sessionId,
                        _currentTransportEpoch.ToString(),
                        RtcRuntimeState.Created.ToString(),
                        RtcRuntimeState.Connecting.ToString(),
                        0,
                        null,
                        null,
                        true,
                        null);
                }
                finally
                {
                    SafeRaiseStatusChanged(
                        RtcRuntimeState.Connecting,
                        transitionVersion);
                }
            }

            if (startLogin)
            {
                try
                {
                    _transport.Connect(() => OnConnected(config), OnConnectFailed);
                }
                catch (Exception error)
                {
                    OnConnectFailed(error.Message);
                }
            }

            return true;
        }

        // 锁内调用：拷贝并清空恢复等待队列。调用方在锁外 Resolve。
        private List<RecoveryLoginWaiter> DetachRecoveryLoginWaitersLocked()
        {
            if (_recoveryLoginWaiters.Count == 0)
            {
                return null;
            }

            List<RecoveryLoginWaiter> waiters =
                new List<RecoveryLoginWaiter>(_recoveryLoginWaiters);
            _recoveryLoginWaiters.Clear();
            return waiters;
        }

        // 锁外调用：TryClaim 保证每个等待者恰好一次回调；completion 内联，
        // callback 经 PostCallback 投递（与 Connected 分支一致）。
        private void ResolveRecoveryLoginWaiters(
            List<RecoveryLoginWaiter> waiters,
            RtcResult<RtcLoginResult> result)
        {
            if (waiters == null)
            {
                return;
            }

            foreach (RecoveryLoginWaiter waiter in waiters)
            {
                waiter.ConsumeTimeoutEntry()?.Dispose();
                if (!waiter.TryClaim())
                {
                    continue;
                }

                // completion 为内部同步契约：与 DispatchLoginCompletions 一致逐个隔离，
                // 单个失败不得中断其余等待者，也不得跳过调用方的状态收尾。
                try
                {
                    waiter.Completion?.Invoke(result);
                }
                catch (Exception error)
                {
                    _logger.Error("recovery login completion", error);
                }

                PostCallback(() => waiter.Callback?.Invoke(result));
            }
        }

        // 只结束该等待者，不影响重连本身。
        private void OnRecoveryLoginWaiterTimeout(RecoveryLoginWaiter waiter)
        {
            lock (_gate)
            {
                waiter.ConsumeTimeoutEntry();
                if (!_recoveryLoginWaiters.Remove(waiter))
                {
                    return; // 结局已先发生，该等待者由 Resolve 结束。
                }
            }

            ResolveRecoveryLoginWaiters(
                new List<RecoveryLoginWaiter> { waiter },
                RtcResult<RtcLoginResult>.Failed(
                    0,
                    RtcResultStatus.Timeout,
                    new RtcError(
                        RtcErrorCode.Timeout,
                        0,
                        "Login timed out while waiting for reconnect.",
                        false)));
        }

        public IRtcRequestHandle SendRequest(RtcRequest request, Action<RtcResult<RtcResponse>> callback)
        {
            return SendRequestCore(request, callback, null);
        }

        IRtcRequestHandle IRtcRuntimeRequestCompletion.SendRequest(
            RtcRequest request,
            Action<RtcResult<RtcResponse>> callback,
            Action<RtcResult<RtcResponse>> completion)
        {
            return SendRequestCore(request, callback, completion);
        }

        private IRtcRequestHandle SendRequestCore(
            RtcRequest request,
            Action<RtcResult<RtcResponse>> callback,
            Action<RtcResult<RtcResponse>> completion)
        {
            if (request == null)
            {
                return FailRequestImmediately(
                    0,
                    callback,
                    completion,
                    RtcResultStatus.Failed,
                    new RtcError(
                        RtcErrorCode.InvalidArgument,
                        0,
                        "SendRequest request must not be null.",
                        false));
            }

            RtcErrorCode invalidStateCode = RtcErrorCode.NotConnected;
            bool invalidState = false;
            RtcRuntimeState state;
            lock (_gate)
            {
                state = _state;
                if (state != RtcRuntimeState.Connected)
                {
                    // 架构 3.4：Closed 之后所有请求返回 Closed；其他非 Connected 状态返回 NotConnected。
                    invalidState = true;
                    invalidStateCode = state == RtcRuntimeState.Closed
                        ? RtcErrorCode.Closed
                        : RtcErrorCode.NotConnected;
                }
            }

            if (invalidState)
            {
                if (state == RtcRuntimeState.ReconnectFailed)
                {
                    // 当前请求仍立即失败；仅尝试触发后台恢复。
                    // TryReconnect() 自带状态检查和并发去重，且必须在 _gate 锁外调用。
                    TryReconnect();
                }

                return FailRequestImmediately(
                    0,
                    callback,
                    completion,
                    RtcResultStatus.Failed,
                    new RtcError(
                        invalidStateCode,
                        0,
                        $"SendRequest requires Connected state; current={state}",
                        false));
            }

            return SendCore(
                request,
                callback,
                onCompletedSynchronously: completion);
        }

        private IRtcRequestHandle FailRequestImmediately(
            long requestId,
            Action<RtcResult<RtcResponse>> callback,
            Action<RtcResult<RtcResponse>> onCompletedSynchronously,
            RtcResultStatus status,
            RtcError error)
        {
            RtcResult<RtcResponse> result = RtcResult<RtcResponse>.Failed(
                requestId,
                status,
                error);
            var handle = new RtcRequestHandle<RtcResponse>(
                requestId,
                callback == null
                    ? null
                    : r => PostCallback(
                        () => callback?.Invoke(r),
                        RtcCallbackPriority.High));
            handle.Completed += completedResult =>
            {
                try
                {
                    onCompletedSynchronously?.Invoke(completedResult);
                }
                catch (Exception error)
                {
                    _logger.Error("synchronous request completion", error);
                }
            };
            handle.TryComplete(result);
            return handle;
        }

