        public IDisposable RegisterPushHandler(string method, Action<RtcPushEnvelope> handler)
        {
            lock (_gate)
            {
                if (_pushRoutes.TryGetValue(method, out PushRoute route))
                {
                    if (route.Kind == PushRouteKind.Typed)
                    {
                        route.Kind = PushRouteKind.Mixed;
                    }

                    route.GenericHandler += handler;
                }
                else
                {
                    _pushRoutes[method] = new PushRoute
                    {
                        Kind = PushRouteKind.Generic,
                        GenericHandler = handler
                    };
                }
            }

            return new GenericPushSubscription(this, method, handler);
        }

        IDisposable IRtcClientDecodeRuntime.RegisterPushObserver(
            Action<string, RtcDecodedPushMessage> observer)
        {
            if (observer == null)
            {
                return null;
            }

            lock (_gate)
            {
                _pushObserver += observer;
            }

            return new PushObserverSubscription(this, observer);
        }

        bool IRtcClientDecodeRuntime.TryRegisterTypedPushHandler(
            string method,
            Action<RtcDecodedPushMessage> handler,
            out IDisposable subscription)
        {
            subscription = null;
            if (string.IsNullOrEmpty(method) || handler == null)
            {
                return false;
            }

            lock (_gate)
            {
                if (_pushRoutes.TryGetValue(method, out PushRoute route))
                {
                    if (route.Kind == PushRouteKind.Generic)
                    {
                        route.Kind = PushRouteKind.Mixed;
                    }

                    route.TypedHandler += handler;
                }
                else
                {
                    _pushRoutes[method] = new PushRoute
                    {
                        Kind = PushRouteKind.Typed,
                        TypedHandler = handler
                    };
                }
            }

            subscription = new TypedPushSubscription(this, method, handler);
            return true;
        }

        private IRtcRequestHandle FailTypedRequestImmediately(
            Action<RtcDecodedResponseResult> callback,
            Action<RtcDecodedResponseResult> completion,
            RtcError error)
        {
            Action<RtcResult<RtcResponse>> rawCompletion = null;
            if (completion != null)
            {
                rawCompletion = result =>
                    completion(
                        RtcDecodedResponseResult.Failed(
                            result.RequestId,
                            result.Error));
            }

            IRtcRequestHandle handle = FailRequestImmediately(
                0,
                null,
                rawCompletion,
                RtcResultStatus.Failed,
                error);
            if (callback != null)
            {
                RtcDecodedResponseResult result = RtcDecodedResponseResult.Failed(0, error);
                PostCallback(
                    () => callback(result),
                    RtcCallbackPriority.High);
            }

            return handle;
        }

        private void InvokeTypedCompletion(
            Action<RtcDecodedResponseResult> completion,
            RtcDecodedResponseResult result)
        {
            if (completion == null)
            {
                return;
            }

            try
            {
                completion(result);
            }
            catch (Exception error)
            {
                _logger.Error("synchronous typed request completion", error);
            }
        }

        IRtcRequestHandle IRtcClientDecodeRuntime.SendTypedRequest(
            RtcRequest request,
            RtcResponseDecodePlan decodePlan,
            Action<RtcDecodedResponseResult> callback)
        {
            return SendTypedRequestCore(
                request,
                decodePlan,
                callback,
                null);
        }

        IRtcRequestHandle IRtcRuntimeTypedRequestCompletion.SendTypedRequest(
            RtcRequest request,
            RtcResponseDecodePlan decodePlan,
            Action<RtcDecodedResponseResult> callback,
            Action<RtcDecodedResponseResult> completion)
        {
            return SendTypedRequestCore(
                request,
                decodePlan,
                callback,
                completion);
        }

        private IRtcRequestHandle SendTypedRequestCore(
            RtcRequest request,
            RtcResponseDecodePlan decodePlan,
            Action<RtcDecodedResponseResult> callback,
            Action<RtcDecodedResponseResult> completion)
        {
            if (request == null)
            {
                return FailTypedRequestImmediately(
                    callback,
                    completion,
                    new RtcError(
                        RtcErrorCode.InvalidArgument,
                        0,
                        "SendTypedRequest request must not be null.",
                        false));
            }

            if (callback == null)
            {
                return FailTypedRequestImmediately(
                    null,
                    completion,
                    new RtcError(
                        RtcErrorCode.InvalidArgument,
                        0,
                        "SendTypedRequest callback must not be null.",
                        false));
            }

            RtcRuntimeState state;
            lock (_gate)
            {
                state = _state;
            }

            if (state != RtcRuntimeState.Connected)
            {
                RtcDecodedResponseResult result = RtcDecodedResponseResult.Failed(
                    0,
                    new RtcError(
                        state == RtcRuntimeState.Closed
                            ? RtcErrorCode.Closed
                            : RtcErrorCode.NotConnected,
                        0,
                        "SendTypedRequest requires Connected state; current=" + state,
                        false));
                return FailTypedRequestImmediately(
                    callback,
                    completion,
                    result.Error);
            }

            var info = new TypedRequestInfo(
                decodePlan,
                request.Method,
                callback,
                completion);
            int registered = 0;
            return SendCore(
                request,
                result =>
                {
                    if (result.IsSuccess)
                    {
                        return;
                    }

                    TypedRequestInfo removed = null;
                    lock (_gate)
                    {
                        if (_typedRequests.TryGetValue(request.RequestId, out removed))
                        {
                            _typedRequests.Remove(request.RequestId);
                        }
                    }

                    if (removed != null)
                    {
                        removed.Callback(
                            RtcDecodedResponseResult.Failed(
                                request.RequestId,
                                result.Error));
                    }
                    else if (Interlocked.CompareExchange(ref registered, 0, 0) == 0)
                    {
                        // Encoding and the pre-registration close race complete before
                        // SendCore can invoke onRegistered. The typed callback still
                        // belongs to this request and must not be lost.
                        info.Callback(
                            RtcDecodedResponseResult.Failed(
                                request.RequestId,
                                result.Error));
                    }
                },
                requestId =>
                {
                    _typedRequests[requestId] = info;
                    Interlocked.Exchange(ref registered, 1);
                },
                result =>
                {
                    if (!result.IsSuccess)
                    {
                        InvokeTypedCompletion(
                            completion,
                            RtcDecodedResponseResult.Failed(
                                result.RequestId,
                                result.Error));
                    }
                });
        }

        public void Close()
        {
            // 8.12.8：用户 Close 与 kickout 统一走共享收尾（差异只在事件类型/错误码）。
            SessionEndContext sessionEndContext;
            bool closed = CloseShared(
                RtcErrorCode.Closed,
                "Runtime closed.",
                raiseStatusEvent: true,
                sessionEndContext: out sessionEndContext);
            if (closed)
            {
                TryMarkSessionEnded(
                    "session_closed",
                    "user_close",
                    (int)RtcErrorCode.Closed,
                    true,
                    sessionEndContext: sessionEndContext);
                RaiseSessionClosedOnce((int)RtcErrorCode.Closed);
                // Logical close is complete; pending transport operations may
                // finish asynchronously after the next runtime is created.
                CloseTransportSafely("runtime close");
            }
        }

        public void SetReloginPolicy(Func<int, int, bool> shouldRelogin)
        {
            _reloginPolicy = shouldRelogin;
        }

        public bool TryReconnect()
        {
            Func<int, int, bool> policy;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.ReconnectFailed)
                {
                    return false;
                }

                long nowMs = _monotonicClock.ElapsedMilliseconds;
                if (_lastReconnectTriggerAtMs != long.MinValue)
                {
                    long elapsedMs = nowMs - _lastReconnectTriggerAtMs;
                    if (elapsedMs >= 0 && elapsedMs < DefaultReconnectTriggerCooldownMs)
                    {
                        return false;
                    }
                }

                _lastReconnectTriggerAtMs = nowMs;
                policy = _reloginPolicy;
            }

            if (!EvaluateReloginPolicy(policy, RtcReconnectUnknownError, 0))
            {
                return false;
            }

            IDisposable heartbeatSubscription;
            IDisposable reconnectSubscription;
            long transitionVersion;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.ReconnectFailed)
                {
                    return false;
                }

                _generation++;
                _reconnectAttempt = 0;
                _lastReconnectErrorCode = 0;
                _sessionEnded = false;
                _sessionClosedRaised = false;
                _heartbeatGeneration++;
                heartbeatSubscription = DetachTimerEntryLocked(ref _heartbeatEntry);
                reconnectSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                _state = RtcRuntimeState.Reconnecting;
                transitionVersion = RecordStatusTransitionLocked();
            }

            try
            {
                DisposeSubscription(heartbeatSubscription);
                DisposeSubscription(reconnectSubscription);
            }
            finally
            {
                SafeRaiseStatusChanged(
                    RtcRuntimeState.Reconnecting,
                    transitionVersion);
            }
            SafeRaiseReloginWillStart(RtcReconnectUnknownError, 0);
            ScheduleReconnectAttempt();
            return true;
        }

        // 共享关闭收尾：幂等地清 pending/login callback/push handler，返回是否发生了状态切换
        //（false 表示已处于 Closed，调用方无需再处理）。锁外触发状态事件与 callback。
        // 供用户 Close 与 kickout 复用（8.12.8）。
        private bool CloseShared(
            RtcErrorCode errorCode,
            string message,
            bool raiseStatusEvent,
            out SessionEndContext sessionEndContext,
            string closeInitiator = null)
        {
            sessionEndContext = null;
            List<RtcRequestHandle<RtcResponse>> requestsToFail;
            List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>> typedRequestsToFail;
            Action<RtcResult<RtcLoginResult>> loginCallbacksToFail;
            Action<RtcResult<RtcLoginResult>> loginCompletionsToFail;
            IDisposable heartbeatSubscription;
            IDisposable reconnectSubscription;
            bool stateChanged = false;
            RtcRuntimeState previousState;
            int closedTransportEpoch;
            bool pendingLogin;
            List<RecoveryLoginWaiter> recoveryWaiters;
            long transitionVersion = 0;
            lock (_gate)
            {
                if (_state == RtcRuntimeState.Closed)
                {
                    return false; // 幂等：重复关闭不重复清理。
                }

                DetachPendingRequestsLocked(
                    out requestsToFail,
                    out typedRequestsToFail);
                previousState = _state;

                loginCallbacksToFail = _pendingLoginCallbacks;
                loginCompletionsToFail = _pendingLoginCompletions;
                pendingLogin = loginCallbacksToFail != null
                    || loginCompletionsToFail != null;
                recoveryWaiters = DetachRecoveryLoginWaitersLocked();
                sessionEndContext = new SessionEndContext(
                    _currentTransportEpoch.ToString(),
                    _reconnectCycleId);
                _pendingLoginCallbacks = null;
                _pendingLoginCompletions = null;

                // 架构 3.4：关闭后不再投递 Push。
                _pushRoutes.Clear();
                _pushObserver = null;

                // 3.7：关闭后清除当前连接 epoch，防止旧连接迟到 Closed 被接受。
                closedTransportEpoch = _currentTransportEpoch;
                _currentTransportEpoch = 0;

                // 5.1：关闭时取消 Transport 事件订阅，防止未来解耦生命周期时成为 GC root 泄漏。
                _transport.Received -= OnTransportReceived;
                _transport.Closed -= OnTransportClosed;

                _state = RtcRuntimeState.Closed;
                if (raiseStatusEvent)
                {
                    transitionVersion = RecordStatusTransitionLocked();
                }
                _heartbeatGeneration++;
                heartbeatSubscription = DetachTimerEntryLocked(ref _heartbeatEntry);
                reconnectSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                stateChanged = true;
            }

            try
            {
                DisposeSubscription(heartbeatSubscription);
                DisposeSubscription(reconnectSubscription);

                // Complete in-flight requests before publishing SessionEnd so
                // their cancellation accounting enters the session snapshot.
                CompleteDetachedRequests(
                    requestsToFail,
                    typedRequestsToFail,
                    RtcResultStatus.Closed,
                    errorCode,
                    message);

                if (stateChanged)
                {
                    _tracing?.TrackConnectionState(
                        _sessionId,
                        closedTransportEpoch.ToString(),
                        previousState.ToString(),
                        RtcRuntimeState.Closed.ToString(),
                        (int)errorCode,
                        errorCode == RtcErrorCode.Closed ? "user_close" : "remote_close",
                        null,
                        pendingLogin,
                        string.IsNullOrEmpty(closeInitiator)
                            ? (errorCode == RtcErrorCode.Closed
                                ? "user_close"
                                : "transport_closed")
                            : closeInitiator);
                }
            }
            finally
            {
                if (stateChanged && raiseStatusEvent)
                {
                    SafeRaiseStatusChanged(
                        RtcRuntimeState.Closed,
                        transitionVersion);
                }
            }

            // 阶段一：login callback 异步投递（CloseShared 可能在 IO 线程被 kickout 触发）。
            if (pendingLogin)
            {
                TrackLoginResultOnce(
                    "failure",
                    (int)errorCode,
                    0,
                    GetElapsedDurationMs(_loginStartElapsedMs),
                    "closed",
                    "closed_while_login");
            }
            RtcResult<RtcLoginResult> loginResult =
                RtcResult<RtcLoginResult>.Failed(
                    0,
                    RtcResultStatus.Closed,
                    new RtcError(errorCode, 0, message + " while login was pending.", false));
            DispatchLoginCompletions(loginCompletionsToFail, loginResult);
            PostLoginCallbacks(loginCallbacksToFail, loginResult, false);

            // 重连等待者与 pending login 一样在关闭时恰好失败一次。
            ResolveRecoveryLoginWaiters(
                recoveryWaiters,
                RtcResult<RtcLoginResult>.Failed(
                    0,
                    RtcResultStatus.Closed,
                    new RtcError(
                        errorCode,
                        0,
                        "Runtime closed while login was waiting.",
                        false)));

            return true;
        }

        public void Dispose()
        {
            DisposeCore();
        }

        private void DisposeCore()
        {
            if (Interlocked.Exchange(ref _disposed, 1) != 0)
            {
                return;
            }

            try
            {
                Close();
            }
            finally
            {
                // Deliver accepted request/lifecycle callbacks (High) while
                // dropping queued Push callbacks (Normal).
                _dispatcher.Close(drain: true);
            }
        }

        // Login 内部的 auth 请求和业务 SendRequest 共用同一套 pending 表 + 超时机制，
        // 唯一区别是 Login 在状态还是 Connecting（不是 Connected）时也允许发出去。
        private IRtcRequestHandle SendCore(
            RtcRequest request,
            Action<RtcResult<RtcResponse>> callback,
            Action<long> onRegistered = null,
            Action<RtcResult<RtcResponse>> onCompletedSynchronously = null,
            bool isInternalRequest = false)
        {
            int timeoutMs = request.TimeoutMs > 0 ? request.TimeoutMs : (int)_requestTimeoutMs;
            long requestId = 0;
            RtcRequestHandle<RtcResponse> handle = null;
            RtcResult<RtcResponse> closedResult = null;

            lock (_gate)
            {
                if (_state == RtcRuntimeState.Closed)
                {
                    RtcError error = new RtcError(RtcErrorCode.Closed, 0,
                        "SendRequest requires Connected state; current=" + _state, false);
                    // 锁外触发 callback（不在此持锁调用）。
                    closedResult = RtcResult<RtcResponse>.Failed(
                        0,
                        RtcResultStatus.Closed,
                        error);
                }
                else
                {
                    requestId = ++_nextRequestId;
                    request.RequestId = requestId;
                }
            }

            if (closedResult != null)
            {
                return FailRequestImmediately(
                    0,
                    callback,
                    onCompletedSynchronously,
                    closedResult.Status,
                    closedResult.Error);
            }

            // Encode before creating pending state. Encoding errors are caller/protocol
            // failures and must not leave a request waiting for a later timeout.
            RtcFrame frame = default(RtcFrame);
            try
            {
                frame = RtcTlvProtocolEncoder.EncodeTcp(request);
            }
            catch (Exception error)
            {
                RtcErrorCode errorCode = error is ArgumentException
                    ? RtcErrorCode.InvalidArgument
                    : RtcErrorCode.ProtocolError;
                return FailRequestImmediately(
                    requestId,
                    callback,
                    onCompletedSynchronously,
                    RtcResultStatus.Failed,
                    new RtcError(
                        errorCode,
                        0,
                        "Failed to encode request: " + error.Message,
                        false));
            }

            lock (_gate)
            {
                // Recheck after encoding: Close may race with the validation/encoding phase.
                if (_state == RtcRuntimeState.Closed)
                {
                    RtcError error = new RtcError(RtcErrorCode.Closed, 0,
                        "SendRequest requires Connected state; current=" + _state, false);
                    closedResult = RtcResult<RtcResponse>.Failed(
                        0,
                        RtcResultStatus.Closed,
                        error);
                }
                else
                {

                    // 阶段一：业务 callback 异步投递（IO 线程不执行慢业务回调）；Completed 保持同步
                    //（Runtime 摘 pending 必须及时，不能异步延迟导致残留）。
                    handle = new RtcRequestHandle<RtcResponse>(
                        requestId,
                        callback == null
                            ? null
                            : r => PostCallback(
                        () => callback?.Invoke(r)));
                    if (_tracing != null && _tracing.IsEnabled)
                    {
                        _requestTraceInfo[requestId] = new RequestTraceInfo(
                            request.Method,
                            _monotonicClock.ElapsedMilliseconds,
                            timeoutMs,
                            request.Method == RtcGateContract.AuthLogin,
                            isInternalRequest);
                    }
                    handle.Completed += result =>
                    {
                        RequestTraceInfo traceInfo;
                        lock (_gate)
                        {
                            _pendingRequests.Remove(requestId);
                            _pendingRequestUris.Remove(requestId);
                            _requestTraceInfo.TryGetValue(requestId, out traceInfo);
                            _requestTraceInfo.Remove(requestId);
                        }

                        try
                        {
                            onCompletedSynchronously?.Invoke(result);
                        }
                        catch (Exception error)
                        {
                            _logger.Error("synchronous request completion", error);
                        }

                        if (traceInfo == null
                            || traceInfo.IsLoginAuth
                            || traceInfo.IsInternalRequest)
                        {
                            return;
                        }

                        long observedDurationMs = Math.Max(
                            0,
                            _monotonicClock.ElapsedMilliseconds
                                - traceInfo.StartElapsedMs);
                        bool timeout = result.Status == RtcResultStatus.Timeout;
                        long durationMs = timeout
                            ? traceInfo.TimeoutMs
                            : observedDurationMs;
                        bool cancelled = result.Status == RtcResultStatus.Cancelled
                            || result.Status == RtcResultStatus.Closed;
                        bool success = result.IsSuccess;
                        bool slow = success
                            && durationMs >= GetSlowRequestThresholdMs();

                        if (cancelled)
                        {
                            Interlocked.Increment(ref _sessionCancelledRequestCount);
                            _tracing?.AggregateCancelled(traceInfo.Method);
                            return;
                        }

                        _tracing?.AggregateRequest(
                            traceInfo.Method,
                            success,
                            timeout,
                            slow,
                            durationMs);

                        if (!success || timeout || slow)
                        {
                            string resultName = timeout
                                ? "timeout"
                                : (slow ? "slow" : "failure");
                            string failureReason = timeout
                                ? "request_timeout"
                                : (slow
                                    ? "slow_request"
                                    : (string.IsNullOrEmpty(result.Error?.Message)
                                        ? "request_failure"
                                        : result.Error.Message));
                            int errorCode = result.Error == null
                                ? 0
                                : (int)result.Error.Code;
                            int remoteErrorCode = result.Error?.RawServerCode ?? 0;
                            _tracing?.TrackRequestAnomaly(
                                _sessionId,
                                Guid.NewGuid().ToString("N"),
                                "request",
                                traceInfo.Method,
                                resultName,
                                errorCode,
                                remoteErrorCode,
                                requestId,
                                durationMs,
                                failureReason);
                        }
                    };
                    _pendingRequests[requestId] = handle;
                    _pendingRequestUris[requestId] = request.Method;
                    onRegistered?.Invoke(requestId);
                }
            }

            if (closedResult != null)
            {
                if (frame.IsValid)
                {
                    ReturnFrame(ref frame);
                }
                return FailRequestImmediately(
                    0,
                    callback,
                    onCompletedSynchronously,
                    closedResult.Status,
                    closedResult.Error);
            }

            IDisposable timeoutSubscription;
            try
            {
                timeoutSubscription = _timerScheduler.Schedule(
                    TimeSpan.FromMilliseconds(timeoutMs),
                    () => CompleteRequest(requestId, RtcResult<RtcResponse>.Failed(requestId, RtcResultStatus.Timeout,
                        new RtcError(RtcErrorCode.Timeout, 0, "Request timed out.", true))));
            }
            catch (Exception error)
            {
                _logger.Error("request timeout schedule", error);
                CompleteRequest(
                    requestId,
                    RtcResult<RtcResponse>.Failed(
                        requestId,
                        RtcResultStatus.Failed,
                        new RtcError(
                            RtcErrorCode.Unknown,
                            0,
                            "Failed to schedule request timeout.",
                            false)));
                if (frame.IsValid)
                {
                    ReturnFrame(ref frame);
                }
                return handle;
            }

            handle.AttachTimeoutSubscription(timeoutSubscription);

            if (!(_transport is ITlvTransport))
            {
                CompleteRequest(
                    requestId,
                    RtcResult<RtcResponse>.Failed(
                        requestId,
                        RtcResultStatus.Failed,
                        new RtcError(
                            RtcErrorCode.ProtocolError,
                            0,
                            "RTC Runtime requires a TLV transport.",
                            false)));
                if (frame.IsValid)
                {
                    ReturnFrame(ref frame);
                }
                return handle;
            }

            bool accepted = TrySendFrame(ref frame, "request frame send");

            if (!accepted)
            {
                // The transport rejected ownership of this frame (closed,
                // close-after-send, or queue full). Do not leave the request
                // pending until its normal timeout; complete it at the
                // transport boundary. Any later Closed callback is idempotent
                // through RtcRequestHandle.TryComplete.
                CompleteRequest(
                    requestId,
                    RtcResult<RtcResponse>.Failed(
                        requestId,
                        RtcResultStatus.TransportLost,
                        new RtcError(
                            RtcErrorCode.TransportLost,
                            0,
                            "Transport rejected the request frame.",
                            true)));
            }

            return handle;
        }

        private void DetachPendingRequestsLocked(
            out List<RtcRequestHandle<RtcResponse>> requestsToFail,
            out List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>> typedRequestsToFail)
        {
            requestsToFail = new List<RtcRequestHandle<RtcResponse>>();
            typedRequestsToFail =
                new List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>>();

            foreach (KeyValuePair<long, RtcRequestHandle<RtcResponse>> pending in _pendingRequests)
            {
                TypedRequestInfo typedInfo;
                if (_typedRequests.TryGetValue(pending.Key, out typedInfo))
                {
                    typedRequestsToFail.Add(
                        new KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>(
                            pending.Value,
                            typedInfo));
                }
                else
                {
                    requestsToFail.Add(pending.Value);
                }
            }

            _pendingRequests.Clear();
            _pendingRequestUris.Clear();
            _typedRequests.Clear();
            _reliablePushDedupCache.Clear();
        }

        private void CompleteDetachedRequests(
            List<RtcRequestHandle<RtcResponse>> requestsToFail,
            List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>> typedRequestsToFail,
            RtcResultStatus status,
            RtcErrorCode errorCode,
            string message)
        {
            foreach (RtcRequestHandle<RtcResponse> handle in requestsToFail)
            {
                handle.TryComplete(
                    RtcResult<RtcResponse>.Failed(
                        handle.RequestId,
                        status,
                        new RtcError(errorCode, 0, message, status == RtcResultStatus.TransportLost)));
            }

            foreach (KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo> typed in typedRequestsToFail)
            {
                RtcRequestHandle<RtcResponse> handle = typed.Key;
                RtcError error = new RtcError(
                    errorCode,
                    0,
                    message,
                    status == RtcResultStatus.TransportLost);
                RtcResult<RtcResponse> result = RtcResult<RtcResponse>.Failed(
                    handle.RequestId,
                    status,
                    error);
                if (!handle.TryComplete(result))
                {
                    continue;
                }

                RtcDecodedResponseResult typedResult =
                    RtcDecodedResponseResult.Failed(handle.RequestId, error);
                PostCallback(
                    () => typed.Value.Callback(typedResult),
                    RtcCallbackPriority.High);
            }
        }

        private void OnConnected(RtcLoginConfig config)
        {
            RtcLoginConfig authConfig;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connecting)
                {
                    return; // Close 或状态已经变化，忽略迟到的 Connect 回调。
                }

                _currentTransportEpoch = _transport.CurrentEpoch;
                authConfig = _lastLoginConfig ?? config;
            }

            if (IsLoginDeadlineExpired(config))
            {
                FinishLogin(CreateLoginTimeoutResult(0), config);
                return;
            }

            int authTimeoutMs = GetRemainingLoginTimeoutMs(config);
            RtcRequest authRequest = BuildAuthRequest(authConfig, authTimeoutMs);
            SendCore(
                authRequest,
                null,
                onCompletedSynchronously: response => FinishLogin(response, config),
                isInternalRequest: true);
        }

        private void FinishLogin(
            RtcResult<RtcResponse> response,
            RtcLoginConfig config)
        {
            if (response != null
                && response.IsSuccess
                && IsLoginDeadlineExpired(config))
            {
                response = CreateLoginTimeoutResult(response.RequestId);
            }

            bool authAccepted = false;
            if (response.IsSuccess)
            {
                try
                {
                    authAccepted = IsAuthAccepted(response.Value);
                }
                catch (RtcProtocolException error)
                {
                    response = RtcResult<RtcResponse>.Failed(
                        response.RequestId,
                        RtcResultStatus.Failed,
                        new RtcError(
                            RtcErrorCode.ProtocolError,
                            0,
                            "Auth response parse failed: " + error.Message,
                            false));
                }
            }

            RtcResult<RtcLoginResult> loginResult;
            Action<RtcResult<RtcLoginResult>> callbacks;
            Action<RtcResult<RtcLoginResult>> completions;
            string failureReason;
            if (response.Status == RtcResultStatus.Timeout)
            {
                failureReason = "auth_timeout";
            }
            else if (response.Error?.Code == RtcErrorCode.ProtocolError)
            {
                failureReason = "auth_protocol_error";
            }
            else
            {
                failureReason = "auth_request_failed";
            }

            if (!response.IsSuccess)
            {
                if (!TryTransitionInitialLogin(
                    RtcRuntimeState.Created,
                    failureReason,
                    out callbacks,
                    out completions))
                {
                    return;
                }

                TrackLoginResultOnce(
                    "failure",
                    response.Error == null ? 0 : (int)response.Error.Code,
                    response.Error?.RawServerCode ?? 0,
                    response.Status == RtcResultStatus.Timeout
                        ? _requestTimeoutMs
                        : GetElapsedDurationMs(_loginStartElapsedMs),
                    response.Status == RtcResultStatus.Timeout ? "timeout" : "auth.login",
                    failureReason);
                loginResult = RtcResult<RtcLoginResult>.Failed(
                    response.RequestId,
                    response.Status,
                    response.Error);
                DispatchLoginCompletions(completions, loginResult);
                PostLoginCallbacks(callbacks, loginResult, false);
                if (response.Status == RtcResultStatus.Timeout
                    || response.Error?.Code == RtcErrorCode.ProtocolError)
                {
                    DisconnectTransportSafely(
                        response.Error?.Code == RtcErrorCode.ProtocolError
                            ? "login protocol error disconnect"
                            : "login timeout disconnect");
                }
                return;
            }

            if (!authAccepted)
            {
                if (!TryTransitionInitialLogin(
                    RtcRuntimeState.Created,
                    "auth_rejected",
                    out callbacks,
                    out completions))
                {
                    return;
                }

                int remoteErrorCode = ExtractRemoteErrorCode(response.Value.Payload);
                var error = new RtcError(
                    RtcErrorCode.RemoteError,
                    remoteErrorCode,
                    "auth.login answer accepted=false",
                    false);
                TrackLoginResultOnce(
                    "failure",
                    (int)RtcErrorCode.RemoteError,
                    remoteErrorCode,
                    GetElapsedDurationMs(_loginStartElapsedMs),
                    "auth.login",
                    "auth_rejected");
                loginResult = RtcResult<RtcLoginResult>.Failed(
                    response.RequestId,
                    RtcResultStatus.Failed,
                    error);
                DispatchLoginCompletions(completions, loginResult);
                PostLoginCallbacks(callbacks, loginResult, false);
                return;
            }

            if (!TryTransitionInitialLogin(
                RtcRuntimeState.Connected,
                null,
                out callbacks,
                out completions,
                ParseClientTelemetryState(response.Value.Payload)))
            {
                return;
            }

            bool clientTelemetryEnabled = _clientTelemetryEnabled;

            TrackLoginResultOnce(
                "success",
                0,
                0,
                GetElapsedDurationMs(_loginStartElapsedMs),
                null);
            loginResult = RtcResult<RtcLoginResult>.Succeeded(
                response.RequestId,
                new RtcLoginResult
                {
                    ClientTelemetryEnabled = clientTelemetryEnabled
                });
            DispatchLoginCompletions(completions, loginResult);
            PostLoginCallbacks(callbacks, loginResult, true);
        }

        private bool UpdateClientTelemetryState(RtcValue payload)
        {
            bool? serverValue = ParseClientTelemetryState(payload);
            if (serverValue.HasValue)
            {
                _clientTelemetryEnabled = serverValue.Value;
                _tracing?.SetClientTelemetryEnabled(serverValue.Value);
            }

            return _clientTelemetryEnabled;
        }

        private static bool? ParseClientTelemetryState(RtcValue payload)
        {
            if (payload == null || payload.Kind != RtcValueKind.Map)
            {
                return null;
            }

            RtcValue value = payload["telemetry_on"];
            if (value == null || value.Kind != RtcValueKind.Boolean)
            {
                return null;
            }

            return value.BooleanValue;
        }

        // auth.login Answer 是否 accepted==true。
        private bool IsLoginDeadlineExpired(RtcLoginConfig config)
        {
            return config != null
                && config.TimeoutMs > 0
                && GetElapsedDurationMs(_loginStartElapsedMs) >= config.TimeoutMs;
        }

        private int GetRemainingLoginTimeoutMs(RtcLoginConfig config)
        {
            if (config == null || config.TimeoutMs <= 0)
            {
                return 0;
            }

            long remaining = config.TimeoutMs - GetElapsedDurationMs(_loginStartElapsedMs);
            return remaining > int.MaxValue
                ? int.MaxValue
                : (int)Math.Max(1, remaining);
        }

        private static RtcResult<RtcResponse> CreateLoginTimeoutResult(long requestId)
        {
            return RtcResult<RtcResponse>.Failed(
                requestId,
                RtcResultStatus.Timeout,
                new RtcError(
                    RtcErrorCode.Timeout,
                    0,
                    "Login timed out.",
                    true));
        }

        private static bool IsAuthAccepted(RtcResponse response)
        {
            if (response?.Payload == null)
            {
                return false;
            }

            if (response.Payload.Kind != RtcValueKind.Map)
            {
                throw new RtcProtocolException(
                    "Authentication payload must be a MsgPack map.");
            }

            RtcValue acceptedField = response.Payload[RtcGateContract.Accepted];
            return acceptedField.Kind == RtcValueKind.Boolean && acceptedField.BooleanValue;
        }



        private static RtcRequest BuildAuthRequest(
            RtcLoginConfig config,
            int timeoutMs = 0)
        {
            var fields = new List<RtcField>
            {
                RtcField.Of(RtcGateContract.Project, RtcValue.Of(config.ProjectId)),
                RtcField.Of(RtcGateContract.User, RtcValue.Of(config.Uid)),
                RtcField.Of(RtcGateContract.Credential, RtcValue.Of(config.Token ?? string.Empty))
            };

            if (config.Ts != 0)
            {
                fields.Add(RtcField.Of(RtcGateContract.AuthSeconds, RtcValue.Of(config.Ts)));
                fields.Add(RtcField.Of(RtcGateContract.AuthVersion, RtcValue.Of((long)2)));
            }

            if (!string.IsNullOrEmpty(config.Version))
            {
                fields.Add(RtcField.Of(RtcGateContract.ClientVersion, RtcValue.Of(config.Version)));
            }

            if (!string.IsNullOrEmpty(config.Lang))
            {
                fields.Add(RtcField.Of(RtcGateContract.Locale, RtcValue.Of(config.Lang)));
            }

            if (config.Attrs != null && config.Attrs.Count > 0)
            {
                fields.Add(RtcField.Of(RtcGateContract.Props, RtcValue.OfMap(config.Attrs)));
            }

            return new RtcRequest(
                RtcGateContract.AuthLogin,
                RtcValue.OfMap(fields),
                timeoutMs: timeoutMs);
        }

        private void OnConnectFailed(string reason)
        {
            Action<RtcResult<RtcLoginResult>> callbacks;
            Action<RtcResult<RtcLoginResult>> completions;
            if (!TryTransitionInitialLogin(
                RtcRuntimeState.Created,
                string.IsNullOrEmpty(reason) ? "connect_failed" : reason,
                out callbacks,
                out completions))
            {
                return;
            }

            TrackLoginResultOnce(
                "failure",
                (int)RtcErrorCode.TransportLost,
                0,
                GetElapsedDurationMs(_loginStartElapsedMs),
                "connect",
                string.IsNullOrEmpty(reason) ? "connect_failed" : reason);
            RtcResult<RtcLoginResult> loginResult =
                RtcResult<RtcLoginResult>.Failed(
                    0,
                    RtcResultStatus.Failed,
                    new RtcError(RtcErrorCode.TransportLost, 0, reason, true));
            DispatchLoginCompletions(completions, loginResult);
            PostLoginCallbacks(callbacks, loginResult, false);
        }

        private void OnTransportReceived(byte[] frame, int frameLength)
        {
            if (_transport is ITlvTransport)
            {
                RtcTlvFrame tlvFrame = default(RtcTlvFrame);
                bool frameRead = false;
                try
                {
                    tlvFrame = RtcTlvProtocolDecoder.ReadFrame(frame, frameLength);
                    frameRead = true;
                    if (TryDispatchTlvTypedAnswer(tlvFrame))
                    {
                        return;
                    }

                    if (TryDispatchTlvTypedPush(tlvFrame))
                    {
                        return;
                    }

                    HandleTlvMessage(RtcTlvProtocolDecoder.Decode(tlvFrame));
                }
                catch (RtcProtocolException error)
                {
                    LogTransportError("TLV receive protocol error", error);
                    CompleteTlvReceiveFailure(
                        tlvFrame,
                        frameRead,
                        RtcErrorCode.ProtocolError,
                        "TLV receive protocol error: " + error.Message);
                    lock (_gate)
                    {
                        _pendingDisconnectReason = RtcCloseReason.FramingError;
                        _pendingDisconnectEpoch = _currentTransportEpoch;
                    }

                    DisconnectTransportSafely("protocol receive disconnect");
                }
                catch (Exception error)
                {
                    LogTransportError("TLV receive dispatch error", error);
                    CompleteTlvReceiveFailure(
                        tlvFrame,
                        frameRead,
                        RtcErrorCode.Unknown,
                        "TLV receive dispatch failed: " + error.Message);
                    lock (_gate)
                    {
                        _pendingDisconnectReason = RtcCloseReason.SocketError;
                        _pendingDisconnectEpoch = _currentTransportEpoch;
                    }

                    DisconnectTransportSafely("TLV receive dispatch failure");
                }

                return;
            }

            // RTC Runtime 只接受 TLV transport；旧 FPNN frame decoder 不再参与运行时。
            DisconnectTransportSafely("unsupported transport disconnect");
        }

        private void CompleteTlvReceiveFailure(
            RtcTlvFrame frame,
            bool frameRead,
            RtcErrorCode errorCode,
            string message)
        {
            if (!frameRead || !IsPendingTlvAnswer(frame))
            {
                return;
            }

            CompleteRequest(
                frame.Sequence,
                RtcResult<RtcResponse>.Failed(
                    frame.Sequence,
                    RtcResultStatus.Failed,
                    new RtcError(errorCode, 0, message, false)));
        }

        private bool IsPendingTlvAnswer(RtcTlvFrame frame)
        {
            string expectedUri;
            lock (_gate)
            {
                if (!_pendingRequestUris.TryGetValue(frame.Sequence, out expectedUri))
                {
                    return false;
                }
            }

            if (frame.Metadata.HasMessageType
                && frame.Metadata.MessageType != RtcTlvMessageType.Answer)
            {
                return false;
            }

            return frame.Uri == RtcGateContract.ControlError
                || string.Equals(expectedUri, frame.Uri, StringComparison.Ordinal);
        }

        private bool TryDispatchTlvTypedAnswer(RtcTlvFrame frame)
        {
            RtcTlvMessageType messageType;
            if (frame.Metadata.HasMessageType)
            {
                messageType = frame.Metadata.MessageType;
            }
            else if (!TryInferTlvMessageType(frame.Uri, out messageType))
            {
                if (!HasPendingRequest(frame.Sequence))
                {
                    return false;
                }

                // A pending typed request is the compatibility fallback for
                // answer frames that omit TLV metadata.
                messageType = RtcTlvMessageType.Answer;
            }

            if (messageType != RtcTlvMessageType.Answer
                || frame.Uri == RtcGateContract.ControlError)
            {
                return false;
            }

            TypedRequestInfo info;
            lock (_gate)
            {
                if (!_typedRequests.TryGetValue(frame.Sequence, out info))
                {
                    return false;
                }

                if (!string.Equals(
                        info.ExpectedUri,
                        frame.Uri,
                        StringComparison.Ordinal))
                {
                    return false;
                }
            }

            RtcDecodedResponse decoded;
            try
            {
                if (!RtcTypedResponseDecoder.TryDecodePayload(
                        frame.Buffer,
                        frame.FrameLength,
                        frame.PayloadOffset,
                        frame.PayloadLength,
                        info.Plan,
                        out decoded))
                {
                    return false;
                }
            }
            catch
            {
                // Let the existing decoded-message path preserve its
                // protocol-error behavior for malformed typed payloads.
                return false;
            }

            if (!frame.Metadata.HasMessageType)
            {
                ReportMissingTlvMetadataMessageType(frame.Uri, frame.Sequence);
            }

            lock (_gate)
            {
                if (!_typedRequests.TryGetValue(frame.Sequence, out info))
                {
                    // Timeout/Close won the request race while decoding.
                    return true;
                }

                _typedRequests.Remove(frame.Sequence);
            }

            uint requestId = frame.Sequence;
            RtcDecodedResponseResult typedResult =
                new RtcDecodedResponseResult(
                    requestId,
                    true,
                    null,
                    decoded);
            PostCallback(
                () => info.Callback(typedResult),
                RtcCallbackPriority.High);
            bool completed = CompleteRequest(
                requestId,
                RtcResult<RtcResponse>.Succeeded(
                    requestId,
                    new RtcResponse(
                        requestId,
                        frame.Uri,
                        RtcResponseStatus.Succeeded,
                        RtcValue.EmptyMap,
                        null)));
            if (completed)
            {
                InvokeTypedCompletion(info.Completion, typedResult);
            }
            return true;
        }

        private bool TryDispatchTlvTypedPush(RtcTlvFrame frame)
        {
            if (!IsReliablePushUri(frame.Uri)
                || (frame.Metadata.HasMessageType
                    && frame.Metadata.MessageType == RtcTlvMessageType.Answer))
            {
                return false;
            }

            PushRoute route;
            lock (_gate)
            {
                if (!_pushRoutes.TryGetValue(frame.Uri, out route)
                    || route.Kind != PushRouteKind.Typed)
                {
                    // Mixed routes deliberately use the decoded fallback so
                    // the typed and generic handlers share one RtcValue.
                    return false;
                }
            }

            RtcDecodedPushMessage decoded;
            try
            {
                if (!RtcTypedDecoder.TryDecodePushPayload(
                        frame.Buffer,
                        frame.FrameLength,
                        frame.Uri,
                        frame.PayloadOffset,
                        frame.PayloadLength,
                        frame.Sequence,
                        out decoded))
                {
                    return false;
                }
            }
            catch
            {
                // Fall back to the existing RtcValue path for malformed or
                // unsupported payload variants.
                return false;
            }

            if (!frame.Metadata.HasMessageType)
            {
                ReportMissingTlvMetadataMessageType(frame.Uri, frame.Sequence);
            }

            ReliablePushKey pushKey;
            if (!TryGetReliablePushKey(frame.Uri, decoded, out pushKey))
            {
                SendTlvAck(frame.Sequence);
                ReportInvalidReliablePush(frame.Uri, frame.Sequence);
                return true;
            }

            if (IsDuplicateTlvPush(pushKey))
            {
                SendTlvAck(frame.Sequence);
                return true;
            }

            SendTlvAck(frame.Sequence);
            NotifyPushObserver(frame.Uri, decoded);
            DispatchTypedPush(frame.Uri, decoded, route);
            return true;
        }

        private void HandleTlvMessage(RtcTlvDecodedMessage decoded)
        {
            bool metadataHasMessageType = decoded.Metadata.HasMessageType;
            RtcTlvMessageType messageType;
            if (metadataHasMessageType)
            {
                messageType = decoded.Metadata.MessageType;
            }
            else if (!TryInferTlvMessageType(decoded.Uri, out messageType)
                && !HasPendingRequest(decoded.Sequence))
            {
                throw new RtcProtocolException(
                    "TLV message type metadata is missing for an unknown URI: "
                    + decoded.Uri);
            }

            if (!metadataHasMessageType)
            {
                ReportMissingTlvMetadataMessageType(decoded);
            }

            if (messageType == RtcTlvMessageType.Answer)
            {
                if (!IsExpectedUri(decoded.Sequence, decoded.Uri)
                    && decoded.Uri != RtcGateContract.ControlError)
                {
                    return;
                }

                if (TryDispatchTlvTypedAnswer(decoded))
                {
                    return;
                }

                if (decoded.Uri == RtcGateContract.ControlError)
                {
                    int remoteErrorCode = ExtractRemoteErrorCode(decoded.Payload);
                    CompleteRequest(
                        decoded.Sequence,
                        RtcResult<RtcResponse>.Failed(
                            decoded.Sequence,
                            RtcResultStatus.Failed,
                            RtcErrorCodeMapper.ToError(
                                remoteErrorCode,
                                ExtractRemoteErrorReason(decoded.Payload))));
                }
                else
                {
                    CompleteRequest(
                        decoded.Sequence,
                        RtcResult<RtcResponse>.Succeeded(
                            decoded.Sequence,
                            new RtcResponse(
                                decoded.Sequence,
                                decoded.Uri,
                                RtcResponseStatus.Succeeded,
                                decoded.Payload,
                                null)));
                }

                return;
            }

            if (decoded.Uri == RtcGateContract.ControlAck)
            {
                return;
            }

            if (decoded.Uri == RtcGateContract.EventKicked)
            {
                CloseByKickout();
                return;
            }

            if (decoded.Uri == RtcGateContract.EventRoomRemoved)
            {
                long roomId = 0;
                if (decoded.Payload != null && decoded.Payload.Kind == RtcValueKind.Map)
                {
                    RtcValue rid = decoded.Payload[RtcGateContract.RoomRef];
                    if (rid.Kind == RtcValueKind.Int64)
                    {
                        roomId = rid.Int64Value;
                    }
                }

                SafeRaiseKickoutRoom(roomId);
                return;
            }

            bool reliablePush = IsReliablePushUri(decoded.Uri);
            if (messageType == RtcTlvMessageType.TwoWayQuest && !reliablePush)
            {
                SendTlvAnswer(decoded.Sequence, decoded.Uri, RtcValue.EmptyMap);
            }

            if (reliablePush)
            {
                ReliablePushKey pushKey;
                if (!TryGetReliablePushKey(
                    decoded.Uri,
                    decoded.Payload,
                    out pushKey))
                {
                    SendTlvAck(decoded.Sequence);
                    ReportInvalidReliablePush(decoded);
                    return;
                }

                if (IsDuplicateTlvPush(pushKey))
                {
                    SendTlvAck(decoded.Sequence);
                    return;
                }
                SendTlvAck(decoded.Sequence);
            }

            RtcDecodedPushMessage decodedPush;
            bool pushDecoded;
            try
            {
                pushDecoded = RtcTypedDecoder.TryDecodePushPayload(
                    decoded.Payload,
                    decoded.Uri,
                    decoded.Sequence,
                    out decodedPush);
            }
            catch
            {
                decodedPush = default(RtcDecodedPushMessage);
                pushDecoded = false;
            }
            if (pushDecoded)
            {
                NotifyPushObserver(decoded.Uri, decodedPush);
            }

            if (TryDispatchTlvTypedPush(decoded, decodedPush, pushDecoded))
            {
                return;
            }

            DispatchTlvPush(decoded.Uri, decoded.Payload);
        }

        private void NotifyPushObserver(
            string method,
            RtcDecodedPushMessage decoded)
        {
            if (!IsBusinessTelemetryEnabled)
            {
                return;
            }

            Action<string, RtcDecodedPushMessage> observer;
            lock (_gate)
            {
                observer = _pushObserver;
            }

            if (observer == null)
            {
                return;
            }

            InvokeEachSubscriber(
                observer,
                handler => ((Action<string, RtcDecodedPushMessage>)handler)(
                    method,
                    decoded));
        }

        private void ReportMissingTlvMetadataMessageType(
            string uri,
            uint sequence)
        {
            uri = uri ?? string.Empty;
            const string dropReason = "tlv_metadata_mtype_missing";

            _tracing?.TrackRequestAnomaly(
                _sessionId,
                _loginTraceId,
                "protocol",
                uri,
                "failure",
                0,
                0,
                sequence,
                -1,
                dropReason);

            bool shouldLog;
            lock (_gate)
            {
                shouldLog = !_emptyTlvMetadataMtypeReported;
                if (shouldLog)
                {
                    _emptyTlvMetadataMtypeReported = true;
                }
            }

            if (shouldLog)
            {
                _logger.Error(
                    "TLV Metadata mtype is missing; compatibility inference was used.",
                    new RtcProtocolException(
                        "TLV Metadata mtype is missing for URI: " + uri));
            }
        }

        private void ReportMissingTlvMetadataMessageType(RtcTlvDecodedMessage decoded)
        {
            ReportMissingTlvMetadataMessageType(decoded.Uri, decoded.Sequence);
        }

        private bool TryDispatchTlvTypedAnswer(RtcTlvDecodedMessage message)
        {
            TypedRequestInfo info;
            lock (_gate)
            {
                if (!_typedRequests.TryGetValue(message.Sequence, out info))
                {
                    return false;
                }

                if (message.Uri != RtcGateContract.ControlError
                    && !string.Equals(
                        info.ExpectedUri,
                        message.Uri,
                        StringComparison.Ordinal))
                {
                    return false;
                }

                _typedRequests.Remove(message.Sequence);
            }

            uint requestId = message.Sequence;
            if (message.Uri == RtcGateContract.ControlError)
            {
                int remoteErrorCode = ExtractRemoteErrorCode(message.Payload);
                RtcError error = RtcErrorCodeMapper.ToError(
                    remoteErrorCode,
                    ExtractRemoteErrorReason(message.Payload));
                PostCallback(
                    () => info.Callback(
                        RtcDecodedResponseResult.Failed(requestId, error)),
                    RtcCallbackPriority.High);
                CompleteRequest(
                    requestId,
                    RtcResult<RtcResponse>.Failed(
                        requestId,
                        RtcResultStatus.Failed,
                        error));
                return true;
            }

            try
            {
                RtcDecodedResponse decoded;
                if (RtcTypedResponseDecoder.TryDecode(
                        message.Payload,
                        info.Plan,
                        out decoded))
                {
                    RtcDecodedResponseResult typedResult =
                        new RtcDecodedResponseResult(
                            requestId,
                            true,
                            null,
                            decoded);
                    PostCallback(
                        () => info.Callback(typedResult),
                        RtcCallbackPriority.High);
                    bool completed = CompleteRequest(
                        requestId,
                        RtcResult<RtcResponse>.Succeeded(
                            requestId,
                            new RtcResponse(
                                requestId,
                                message.Uri,
                                RtcResponseStatus.Succeeded,
                                message.Payload,
                                null)));
                    if (completed)
                    {
                        InvokeTypedCompletion(info.Completion, typedResult);
                    }
                }
                else
                {
                    throw new RtcProtocolException("Typed TLV response decode failed.");
                }
            }
            catch (Exception exception)
            {
                RtcError error = new RtcError(
                    RtcErrorCode.ProtocolError,
                    0,
                    "Typed TLV response decode failed: " + exception.Message,
                    false);
                PostCallback(
                    () => info.Callback(
                        RtcDecodedResponseResult.Failed(requestId, error)),
                    RtcCallbackPriority.High);
                CompleteRequest(
                    requestId,
                    RtcResult<RtcResponse>.Failed(
                        requestId,
                        RtcResultStatus.Failed,
                        error));
            }

            return true;
        }

        private bool TryDispatchTlvTypedPush(
            RtcTlvDecodedMessage message,
            RtcDecodedPushMessage decoded,
            bool decodedSuccessfully)
        {
            PushRoute route;
            lock (_gate)
            {
                if (!_pushRoutes.TryGetValue(message.Uri, out route)
                    || (route.Kind != PushRouteKind.Typed
                        && route.Kind != PushRouteKind.Mixed))
                {
                    return false;
                }

                if (route.Kind == PushRouteKind.Mixed)
                {
                    // Generic has precedence when both routes are registered.
                    // Returning false sends the message through DispatchTlvPush
                    // below, so the Typed handler is not invoked.
                    return false;
                }
            }

            if (!decodedSuccessfully)
            {
                return false;
            }

            if (!_firstPushReceived)
            {
                _firstPushReceived = true;
                long latencyMs = _sessionStartElapsedMs < 0
                    ? -1
                    : GetElapsedDurationMs(_sessionStartElapsedMs);
                _tracing?.SetFirstPushLatency(latencyMs);
            }

            DispatchTypedPush(message.Uri, decoded, route);
            return true;
        }

        private void DispatchTypedPush(
            string method,
            RtcDecodedPushMessage decoded,
            PushRoute route)
        {
            RtcCallbackPostResult postResult = TryPostCallback(
                () =>
                {
                    bool handlerFailed = InvokeEachSubscriber(
                        route.TypedHandler,
                        handler => ((Action<RtcDecodedPushMessage>)handler)(decoded));
                    if (handlerFailed)
                    {
                        _tracing?.AggregatePush(method, false, false, true);
                        TrackPushDropped(method, "handler_exception");
                    }
                },
                RtcCallbackPriority.Normal);

            bool accepted = postResult == RtcCallbackPostResult.Accepted;
            _tracing?.AggregatePush(method, true, accepted, !accepted);
            if (!accepted)
            {
                TrackPushDropped(
                    method,
                    GetCallbackPostFailureReason(postResult));
            }
        }

        private static bool TryInferTlvMessageType(
            string uri,
            out RtcTlvMessageType messageType)
        {
            if (uri == RtcGateContract.EventDirect
                || uri == RtcGateContract.EventGroup
                || uri == RtcGateContract.EventRoom
                || uri == RtcGateContract.EventBroadcast)
            {
                messageType = RtcTlvMessageType.TwoWayQuest;
                return true;
            }

            if (uri == RtcGateContract.EventKicked
                || uri == RtcGateContract.EventRoomRemoved)
            {
                messageType = RtcTlvMessageType.OneWayQuest;
                return true;
            }

            if (uri == RtcGateContract.ControlPing)
            {
                messageType = RtcTlvMessageType.TwoWayQuest;
                return true;
            }

            messageType = default(RtcTlvMessageType);
            return false;
        }

        private bool HasPendingRequest(uint sequence)
        {
            lock (_gate)
            {
                return _pendingRequestUris.ContainsKey(sequence);
            }
        }

        private static bool IsReliablePushUri(string uri)
        {
            return uri == RtcGateContract.EventDirect
                || uri == RtcGateContract.EventGroup
                || uri == RtcGateContract.EventRoom
                || uri == RtcGateContract.EventBroadcast;
        }

        private static bool TryGetReliablePushKey(
            string method,
            RtcValue payload,
            out ReliablePushKey key)
        {
            key = default(ReliablePushKey);
            if (payload == null || payload.Kind != RtcValueKind.Map)
            {
                return false;
            }

            RtcValue mid = payload[RtcGateContract.MessageRef];
            if (mid == null || mid.Kind != RtcValueKind.Int64)
            {
                return false;
            }

            long messageRef = mid.Int64Value;
            if (messageRef <= 0)
            {
                return false;
            }

            ReliablePushCategory category;
            long businessId = 0;
            switch (method)
            {
                case RtcGateContract.EventDirect:
                    category = ReliablePushCategory.Direct;
                    businessId = ReadOptionalInt64(
                        payload[RtcGateContract.Recipient]);
                    if (businessId == 0)
                    {
                        businessId = ReadOptionalInt64(payload["to"]);
                    }
                    break;
                case RtcGateContract.EventGroup:
                    category = ReliablePushCategory.Group;
                    businessId = ReadOptionalInt64(
                        payload[RtcGateContract.GroupRef]);
                    if (businessId == 0)
                    {
                        businessId = ReadOptionalInt64(payload["gid"]);
                    }
                    break;
                case RtcGateContract.EventRoom:
                    category = ReliablePushCategory.Room;
                    businessId = ReadOptionalInt64(
                        payload[RtcGateContract.RoomRef]);
                    if (businessId == 0)
                    {
                        businessId = ReadOptionalInt64(payload["rid"]);
                    }
                    break;
                case RtcGateContract.EventBroadcast:
                    category = ReliablePushCategory.Broadcast;
                    break;
                default:
                    return false;
            }

            long senderId = ReadOptionalInt64(payload[RtcGateContract.Sender]);
            if (senderId == 0)
            {
                senderId = ReadOptionalInt64(payload["from"]);
            }

            key = new ReliablePushKey(
                category,
                businessId,
                senderId,
                messageRef);
            return true;
        }

        private static bool TryGetReliablePushKey(
            string method,
            RtcDecodedPushMessage payload,
            out ReliablePushKey key)
        {
            key = default(ReliablePushKey);
            if (!payload.HasMessageId || payload.MessageId <= 0)
            {
                return false;
            }

            ReliablePushCategory category;
            long businessId = 0;
            switch (method)
            {
                case RtcGateContract.EventDirect:
                    category = ReliablePushCategory.Direct;
                    businessId = payload.TargetId;
                    break;
                case RtcGateContract.EventGroup:
                    category = ReliablePushCategory.Group;
                    businessId = payload.TargetId;
                    break;
                case RtcGateContract.EventRoom:
                    category = ReliablePushCategory.Room;
                    businessId = payload.TargetId;
                    break;
                case RtcGateContract.EventBroadcast:
                    category = ReliablePushCategory.Broadcast;
                    break;
                default:
                    return false;
            }

            key = new ReliablePushKey(
                category,
                businessId,
                payload.FromUid,
                payload.MessageId);
            return true;
        }

        private static long ReadOptionalInt64(RtcValue value)
        {
            return value != null && value.Kind == RtcValueKind.Int64
                ? value.Int64Value
                : 0;
        }

        private bool IsDuplicateTlvPush(ReliablePushKey key)
