        private static int ExtractRemoteErrorCode(RtcValue payload)
        {
            if (payload == null || payload.Kind != RtcValueKind.Map)
            {
                return 0;
            }

            RtcValue status = payload["status"];
            return status.Kind == RtcValueKind.Int64 ? (int)status.Int64Value : 0;
        }

        private static string ExtractRemoteErrorReason(RtcValue payload)
        {
            if (payload == null || payload.Kind != RtcValueKind.Map)
            {
                return "Remote returned an error answer.";
            }

            RtcValue reason = payload["reason"];
            return reason.Kind == RtcValueKind.String
                ? reason.StringValue
                : "Remote returned an error answer.";
        }

        // 服务端主动发起的双向 quest。"control.ping" 心跳是特例：只更新心跳时间、回一个空 Answer。
        // 其它双向 quest（真实网关的 pushmsg/pushgroupmsg/pushroommsg/pushbroadcastmsg 等
        // 推送消息，实测确认是双向 quest，不是单向——对齐
        // Assets/Plugins/rtm/RTMQuestProcessor.cs 里 PushMessage 等方法开头的
        // AdvanceAnswer.SendAnswer(new Answer(quest))，客户端必须先回一个 Answer 确认收到，
        // 不回复的话服务端可能认为投递失败而重推）统一按"先回 Answer，再转发给业务层"处理，
        // 跟单向 quest 走同一条 DispatchPush 路径，业务层自己按 method/字段过滤识别不了的类型。


        // 已知服务端 push method（对齐 RTM RTMMasterProcessor.methodMap）。
        // 被服务端踢下线：与用户 Close 不同，kickout 是异常关闭，需要触发 SessionClosed
        // （对齐 RTM 语义：kickout 触发 Kickout + SessionClosed + 连接关闭）。
        private void CloseByKickout()
        {
            // 8.12.8：kickout 也走共享关闭收尾（清 pending/login/push handler），
            // 不再只 SetState + Close 导致 pending 等 timeout。差异：kickout 触发 SessionClosed。
            // P0-1：用 CloseAfterSend 而非 Close——kickout 的 ACK（对双向 kickout quest 的成功
            // Answer）已在 HandleTwoWayQuest 中入队，必须先发完 ACK 再关闭连接，否则 ACK 会被
            // CloseOnce 的队列清理吞掉，服务端会重试 kickout。
            RtcRuntimeState state;
            int transportEpoch;
            lock (_gate)
            {
                state = _state;
                transportEpoch = _currentTransportEpoch;
            }
            _logger.Log(
                "event=kickout_received transport_epoch="
                + transportEpoch
                + " state="
                + state);

            SessionEndContext sessionEndContext;
            if (CloseShared(
                RtcErrorCode.RemoteError,
                "Kicked out by server.",
                raiseStatusEvent: false,
                sessionEndContext: out sessionEndContext,
                closeInitiator: "kickout"))
            {
                CloseTransportAfterSendSafely("kickout close-after-send");
            }

            TryMarkSessionEnded(
                RtcGateContract.EventKicked,
                RtcGateContract.EventKicked,
                (int)RtcErrorCode.RemoteError,
                false,
                sessionEndContext: sessionEndContext);
            RaiseKickoutAndSessionClosedOnce(0);
        }



        private bool TrySendFrame(ref RtcFrame frame, string context)
        {
            try
            {
                bool accepted = _transport.Send(ref frame);

                if (!accepted && frame.IsValid)
                {
                    ReturnFrame(ref frame);
                }

                return accepted;
            }
            catch (Exception error)
            {
                // Ownership was not transferred when Send throws and the frame
                // is still valid. Return it exactly once before recovering the
                // current connection through the existing Closed path.
                if (frame.IsValid)
                {
                    ReturnFrame(ref frame);
                }

                LogTransportError(context, error);
                DisconnectTransportSafely(context);
                return false;
            }
        }

        private void DisconnectTransportSafely(string context)
        {
            int epoch;
            bool wasConnected;
            lock (_gate)
            {
                epoch = _currentTransportEpoch;
                wasConnected = _state == RtcRuntimeState.Connected;
            }

            try
            {
                _transport.Disconnect();
            }
            catch (Exception error)
            {
                LogTransportError(context + " disconnect", error);

                bool shouldRecover;
                lock (_gate)
                {
                    shouldRecover = wasConnected
                        && _state == RtcRuntimeState.Connected
                        && _currentTransportEpoch == epoch;
                }

                if (shouldRecover)
                {
                    try
                    {
                        OnTransportClosed(epoch, RtcCloseReason.SocketError);
                    }
                    catch (Exception recoveryError)
                    {
                        LogTransportError(context + " recovery", recoveryError);
                    }
                }
            }
        }

        private void CloseTransportSafely(string context)
        {
            try
            {
                _transport.Close();
            }
            catch (Exception error)
            {
                LogTransportError(context, error);
            }
        }

        private void CloseTransportAfterSendSafely(string context)
        {
            try
            {
                _transport.CloseAfterSend();
            }
            catch (Exception error)
            {
                LogTransportError(context, error);
            }
        }

        private void LogTransportError(string context, Exception error)
        {
            try
            {
                _logger.Error(context, error);
            }
            catch
            {
                // A logging sink is external code; it must not break transport
                // recovery or leak an exception through the SDK boundary.
            }
        }

        private static void ReturnFrame(ref RtcFrame frame)
        {
            if (!frame.IsValid)
            {
                return;
            }

            ArrayPool<byte>.Shared.Return(frame.Buffer);
            RtcPoolDiagnostics.RecordReturn();
            frame.Clear();
        }

        // 回错误 Answer（如未知 method）。payload 对齐 FPNN Answer.FillErrorInfo 的
        // code/ex 字段（fpnn/proto/Answer.cs:58-63）。




        private void DispatchTlvPush(string method, RtcValue payload)
        {
            if (!_firstPushReceived)
            {
                _firstPushReceived = true;
                long latencyMs = _sessionStartElapsedMs < 0
                    ? -1
                    : GetElapsedDurationMs(_sessionStartElapsedMs);
                _tracing?.SetFirstPushLatency(latencyMs);
            }

            PushRoute route;
            lock (_gate)
            {
                if (!_pushRoutes.TryGetValue(method, out route)
                    || (route.Kind != PushRouteKind.Generic
                        && route.Kind != PushRouteKind.Mixed))
                {
                    _tracing?.AggregatePush(method, true, false, true);
                    _tracing?.TrackRequestAnomaly(
                        _sessionId,
                        Guid.NewGuid().ToString("N"),
                        "push_dispatch",
                        method,
                        "dropped",
                        0,
                        0,
                        0,
                        -1,
                        "no_handler");
                    return;
                }
            }

            _tracing?.AggregatePush(method, true, false, false);
            RtcPushEnvelope envelope = new RtcPushEnvelope(method, payload);
            RtcCallbackPostResult postResult = TryPostCallback(
                () =>
                {
                    bool handlerFailed = InvokeEachSubscriber(
                        route.GenericHandler,
                        handler => ((Action<RtcPushEnvelope>)handler)(envelope));
                    if (handlerFailed)
                    {
                        _tracing?.AggregatePush(method, false, false, true);
                        TrackPushDropped(method, "handler_exception");
                    }
                },
                RtcCallbackPriority.Normal);
            bool accepted = postResult == RtcCallbackPostResult.Accepted;
            _tracing?.AggregatePush(method, false, accepted, !accepted);
            if (!accepted)
            {
                TrackPushDropped(
                    method,
                    GetCallbackPostFailureReason(postResult));
            }
        }





        private bool CompleteRequest(long requestId, RtcResult<RtcResponse> result)
        {
            RtcRequestHandle<RtcResponse> handle;
            lock (_gate)
            {
                _pendingRequests.TryGetValue(requestId, out handle);
            }

            bool completed = handle != null && handle.TryComplete(result);
            if (completed)
            {
                lock (_gate)
                {
                    _pendingRequestUris.Remove(requestId);
                }
            }

            return completed;
        }

        private bool IsExpectedUri(uint sequence, string uri)
        {
            lock (_gate)
            {
                string expected;
                if (!_pendingRequestUris.TryGetValue(sequence, out expected))
                {
                    return true;
                }

                return string.Equals(expected, uri, StringComparison.Ordinal);
            }
        }

        private void OnTransportClosed(int epoch, RtcCloseReason reason)
        {
            RtcRuntimeState state;
            RtcCloseReason effectiveReason;
            ReconnectAuthFinishResult authFinish = ReconnectAuthFinishResult.NoActiveAttempt;
            ReconnectAuthFailure authFailure = null;
            lock (_gate)
            {
                // 3.7：只接受当前连接的 Closed。旧连接（旧 epoch）的迟到事件直接丢弃——
                // 防止连接替换/重连竞态下旧连接的关闭事件误触发重连。
                if (epoch != _currentTransportEpoch)
                {
                    return;
                }

                effectiveReason = _pendingDisconnectEpoch == epoch
                    && _pendingDisconnectReason.HasValue
                    ? _pendingDisconnectReason.Value
                    : reason;
                _pendingDisconnectReason = null;
                _pendingDisconnectEpoch = 0;
                state = _state;
                if (state == RtcRuntimeState.Reconnecting)
                {
                    // Invalidate and reserve failure completion before releasing
                    // the same lock used by the successful state commit.
                    authFinish = TryFinalizeReconnectAuthFailureLocked(
                        _reconnectAuthAttempt,
                        "Transport closed while reconnecting: " + effectiveReason,
                        true,
                        out authFailure);
                }
            }

            // P1-4：按 Runtime 状态分派 Closed 处理，避免 Connecting/Reconnecting 阶段
            // 的连接关闭只能等 request timeout 才感知（liveness 问题）。
            switch (state)
            {
                case RtcRuntimeState.Connected:
                    HandleConnectedClosed(effectiveReason);
                    break;

                case RtcRuntimeState.Connecting:
                    // 登录阶段连接关闭：清 pending（auth request 会以 TransportLost 完成，
                    // 经 FinishLogin 失败路径回 Created 并触发 login callback），不等 timeout。
                    FailPendingRequests("Transport closed while connecting: " + effectiveReason);
                    break;

                case RtcRuntimeState.Reconnecting:
                    // 重连阶段连接关闭：按一次失败的重连尝试处理（计数 + 继续退避或进入
                    // ReconnectFailed）。先清理当前 auth，避免它的 timeout 再次计数。
                    if (authFinish == ReconnectAuthFinishResult.Finalized)
                    {
                        CompleteReconnectAuthFailure(authFailure);
                    }
                    else if (authFinish == ReconnectAuthFinishResult.NoActiveAttempt)
                    {
                        OnReconnectFailed("Transport closed while reconnecting: " + effectiveReason);
                    }
                    break;

                default:
                    // Created/Closed：忽略迟到事件。
                    break;
            }
        }

        // 清空 pending 并以 TransportLost 完成它们（auth 等请求经各自回调处理失败）。
        private void FailPendingRequests(string message)
        {
            List<RtcRequestHandle<RtcResponse>> toFail;
            List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>> typedToFail;
            lock (_gate)
            {
                DetachPendingRequestsLocked(
                    out toFail,
                    out typedToFail);
            }

            CompleteDetachedRequests(
                toFail,
                typedToFail,
                RtcResultStatus.TransportLost,
                RtcErrorCode.TransportLost,
                message);
        }

        private bool IsCurrentReconnectAuthAttemptLocked(ReconnectAuthAttempt attempt)
        {
            return _state == RtcRuntimeState.Reconnecting
                && attempt != null
                && ReferenceEquals(_reconnectAuthAttempt, attempt)
                && attempt.Epoch == _currentTransportEpoch;
        }

        private ReconnectAuthFinishResult TryFinalizeReconnectAuthFailureLocked(
            ReconnectAuthAttempt attempt,
            string message,
            bool invalidate,
            out ReconnectAuthFailure failure)
        {
            failure = null;
            if (!IsCurrentReconnectAuthAttemptLocked(attempt))
            {
                return ReconnectAuthFinishResult.NoActiveAttempt;
            }

            if (invalidate)
            {
                attempt.Invalidated = true;
            }
            if (attempt.LifecycleFinished)
            {
                return ReconnectAuthFinishResult.AlreadyFinalized;
            }

            // A claimed auth rejection retains its error/updated-token policy,
            // even when Closed wins the race to finish that failed attempt.
            bool authRejected = attempt.ResultClaimed && !attempt.AuthSucceeded;
            failure = new ReconnectAuthFailure(
                attempt.RequestId,
                attempt.Handle,
                authRejected ? attempt.FailureReason : message,
                authRejected && attempt.StopRetry,
                authRejected ? attempt.ErrorCode : 0);
            attempt.LifecycleFinished = true;
            attempt.RequestId = 0;
            attempt.Handle = null;
            return ReconnectAuthFinishResult.Finalized;
        }

        private ReconnectAuthFinishResult FailReconnectAuth(
            ReconnectAuthAttempt attempt,
            string message)
        {
            ReconnectAuthFailure failure;
            ReconnectAuthFinishResult result;
            lock (_gate)
            {
                result = TryFinalizeReconnectAuthFailureLocked(
                    attempt, message, false, out failure);
            }

            if (result == ReconnectAuthFinishResult.Finalized)
            {
                CompleteReconnectAuthFailure(failure);
            }
            return result;
        }

        private void CompleteReconnectAuthFailure(ReconnectAuthFailure failure)
        {
            try
            {
                if (failure.RequestId != 0)
                {
                    CompleteRequest(failure.RequestId, RtcResult<RtcResponse>.Failed(
                        failure.RequestId,
                        RtcResultStatus.TransportLost,
                        new RtcError(RtcErrorCode.TransportLost, 0, failure.Reason, true)));
                }
                else if (failure.Handle != null && !failure.Handle.IsCompleted)
                {
                    failure.Handle.Cancel();
                }
            }
            finally
            {
                // Only the winner of lifecycle completion may count/schedule
                // a failed retry, including when the request already completed.
                OnReconnectFailed(failure.Reason, failure.StopRetry, failure.ErrorCode);
            }
        }

        private void HandleConnectedClosed(RtcCloseReason reason)
        {
            List<RtcRequestHandle<RtcResponse>> toFail;
            List<KeyValuePair<RtcRequestHandle<RtcResponse>, TypedRequestInfo>> typedToFail;
            IDisposable heartbeatSubscription;
            IDisposable reconnectSubscription;
            int retriedCount;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connected)
                {
                    return; // 状态已变化（如已被并发 Close），忽略。
                }

                DetachPendingRequestsLocked(
                    out toFail,
                    out typedToFail);

                _generation++;
                _reconnectAttempt = 0;
                _lastReconnectErrorCode = 0;
                _heartbeatGeneration++;
                heartbeatSubscription = DetachTimerEntryLocked(ref _heartbeatEntry);
                reconnectSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                retriedCount = _reconnectAttempt;
            }

            DisposeSubscription(heartbeatSubscription);
            DisposeSubscription(reconnectSubscription);

            try
            {
                // 先触发 ReloginWillStart 事件（对齐 RTM 语义），再根据 policy 决定是否重连。
                string reconnectTrigger = ToReconnectTrigger(reason);
                SafeRaiseReloginWillStart(0, retriedCount, reconnectTrigger);

                Func<int, int, bool> policy = _reloginPolicy;
                if (!EvaluateReloginPolicy(policy, 0, retriedCount))
                {
                    // 业务决定不重连：进入 ReconnectFailed，触发 SessionClosed。
                    if (!TrySetStateFrom(
                        RtcRuntimeState.Connected,
                        RtcRuntimeState.ReconnectFailed,
                        "relogin_policy_rejected"))
                    {
                        return;
                    }
                    SafeRaiseReloginCompleted(
                        false,
                        false,
                        RtcReconnectUnknownError,
                        retriedCount,
                        "relogin_policy_rejected");
                    TryMarkSessionEnded(
                        "session_closed",
                        "remote_close",
                        RtcReconnectUnknownError,
                        false,
                        "relogin_policy_rejected");
                    RaiseSessionClosedOnce(RtcReconnectUnknownError);
                    return;
                }

                if (!TrySetStateFrom(
                    RtcRuntimeState.Connected,
                    RtcRuntimeState.Reconnecting,
                    reconnectTrigger))
                {
                    return;
                }
            }
            finally
            {
                // _pendingRequests 已在上面摘除；无论重连事件、策略或状态处理是否抛异常，
                // 都必须让已摘出的请求进入终态，避免业务 await 永久挂起。
                CompleteDetachedRequests(
                    toFail,
                    typedToFail,
                    RtcResultStatus.TransportLost,
                    RtcErrorCode.TransportLost,
                    "Transport closed: " + reason);
            }

            ScheduleReconnectAttempt();
        }

        private bool EvaluateReloginPolicy(
            Func<int, int, bool> policy,
            int errorCode,
            int retriedCount)
        {
            if (policy == null)
            {
                return true;
            }

            try
            {
                return policy(errorCode, retriedCount);
            }
            catch (Exception error)
            {
                // 策略属于业务回调，异常不能反向破坏 Runtime 状态机；按拒绝重连处理，
                // 让自动重连进入 ReconnectFailed，手动 TryReconnect 保持失败返回。
                    _logger.Error("relogin policy", error);
                return false;
            }
        }

        private void ScheduleReconnectAttempt()
        {
            int expectedGeneration;
            int retryCount;
            lock (_gate)
            {
                expectedGeneration = _generation;
                retryCount = _reconnectAttempt + 1;
            }

            int intervalSeconds = _reconnectMaxIntervalSeconds;
            if (retryCount < _reconnectLinearCount)
            {
                intervalSeconds = _reconnectMaxIntervalSeconds * retryCount / _reconnectLinearCount;
            }

            if (intervalSeconds < 1)
            {
                intervalSeconds = 1;
            }

            var entry = new TimerEntry(expectedGeneration);
            IDisposable oldSubscription;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Reconnecting
                    || _generation != expectedGeneration)
                {
                    return;
                }

                oldSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                _reconnectEntry = entry;
            }

            IDisposable subscription;
            try
            {
                subscription = _timerScheduler.Schedule(
                    TimeSpan.FromSeconds(intervalSeconds),
                    () => AttemptReconnect(entry));
            }
            catch (Exception error)
            {
                _logger.Error("reconnect schedule", error);
                lock (_gate)
                {
                    if (ReferenceEquals(_reconnectEntry, entry))
                    {
                        _reconnectEntry = null;
                    }
                }
                DisposeSubscription(oldSubscription);
                OnReconnectFailed(
                    "Reconnect schedule failed: " + error.Message,
                    true,
                    RtcReconnectUnknownError);
                return;
            }

            bool keep;
            lock (_gate)
            {
                keep = _state == RtcRuntimeState.Reconnecting
                    && _generation == expectedGeneration
                    && ReferenceEquals(_reconnectEntry, entry);
                if (keep)
                {
                    entry.Subscription = subscription;
                }
            }

            DisposeSubscription(oldSubscription);
            if (!keep)
            {
                DisposeSubscription(subscription);
            }
        }

        private void AttemptReconnect(TimerEntry entry)
        {
            IDisposable subscription;
            int lastErrorCode;
            int retriedCount;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Reconnecting
                    || _generation != entry.Generation
                    || !ReferenceEquals(_reconnectEntry, entry))
                {
                    return; // 这次调度已经作废（比如期间被手动 Close）。
                }

                _reconnectAuthAttempt = null;
                lastErrorCode = _lastReconnectErrorCode;
                retriedCount = _reconnectAttempt;
                subscription = DetachTimerEntryLocked(ref _reconnectEntry);
            }

            DisposeSubscription(subscription);
            _reconnectStartElapsedMs = _monotonicClock.ElapsedMilliseconds;

            // Publish the Compat retry boundary before starting transport work.
            SafeRaiseReconnectAttemptStarting(lastErrorCode, retriedCount);

            try
            {
                _transport.Connect(OnReconnected, OnReconnectFailed);
            }
            catch (Exception error)
            {
                OnReconnectFailed(error.Message);
            }
        }

        private void OnReconnected()
        {
            RtcLoginConfig config;
            ReconnectAuthAttempt attempt;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Reconnecting)
                {
                    return; // Close 或状态已经变化，忽略迟到的 Connect 回调。
                }

                config = _lastLoginConfig;
                _currentTransportEpoch = _transport.CurrentEpoch;
                attempt = new ReconnectAuthAttempt(
                    ++_reconnectAuthAttemptSequence,
                    _currentTransportEpoch,
                    config?.Token);
                _reconnectAuthAttempt = attempt;
            }

            if (config == null)
            {
                FailReconnectAuth(attempt, "Reconnect has no login config to re-authenticate.");
                return;
            }

            // TCP recovery is not session recovery; re-authenticate first.
            try
            {
                RtcRequest authRequest = BuildAuthRequest(config);
                IRtcRequestHandle authHandle = SendCore(
                    authRequest,
                    response => HandleReconnectAuth(attempt, response),
                    requestId => SetReconnectAuthRequestId(attempt, requestId));

                bool cancelStaleHandle = false;
                bool failBeforeRegistration = false;
                lock (_gate)
                {
                    if (IsCurrentReconnectAuthAttemptLocked(attempt)
                        && !attempt.ResultClaimed
                        && !attempt.Invalidated
                        && !attempt.LifecycleFinished)
                    {
                        attempt.Handle = authHandle;
                        failBeforeRegistration = authHandle == null
                            || (authHandle.IsCompleted && attempt.RequestId == 0);
                    }
                    else
                    {
                        cancelStaleHandle = true;
                    }
                }

                if (cancelStaleHandle)
                {
                    authHandle?.Cancel();
                }
                else if (failBeforeRegistration)
                {
                    FailReconnectAuth(attempt, "Reconnect auth request failed before registration.");
                }
            }
            catch (Exception error)
            {
                FailReconnectAuth(attempt, "Failed to start reconnect auth: " + error.Message);
            }
        }

        private void SetReconnectAuthRequestId(ReconnectAuthAttempt attempt, long requestId)
        {
            lock (_gate)
            {
                if (IsCurrentReconnectAuthAttemptLocked(attempt)
                    && !attempt.ResultClaimed
                    && !attempt.Invalidated
                    && !attempt.LifecycleFinished)
                {
                    attempt.RequestId = requestId;
                }
            }
        }

        private void HandleReconnectAuth(
            ReconnectAuthAttempt attempt,
            RtcResult<RtcResponse> response)
        {
            if (response == null)
            {
                FailReconnectAuth(attempt, "Reconnect auth returned no response.");
                return;
            }

            bool authOk = response.IsSuccess && IsAuthAccepted(response.Value);
            int reconnectAuthErrorCode = ExtractReconnectAuthErrorCode(response, authOk);
            bool stopRetry = !authOk
                && RtcErrorCodeMapper.ShouldStopRelogin(reconnectAuthErrorCode);
            int retriedCount;
            lock (_gate)
            {
                if (!IsCurrentReconnectAuthAttemptLocked(attempt)
                    || attempt.ResultClaimed
                    || attempt.Invalidated
                    || attempt.LifecycleFinished
                    || attempt.RequestId != response.RequestId)
                {
                    return; // 旧连接/已失效的 auth 回调不能恢复新连接状态。
                }

                attempt.ResultClaimed = true;
                attempt.AuthSucceeded = authOk;
                attempt.RequestId = 0;
                attempt.Handle = null;
                if (!authOk && stopRetry
                    && _lastLoginConfig != null
                    && _lastLoginConfig.Token != attempt.Token)
                {
                    // 认证被拒可能只是因为带了旧 Token，而业务已经给了新 Token。
                    stopRetry = false;
                }
                attempt.StopRetry = stopRetry;
                attempt.ErrorCode = reconnectAuthErrorCode;
                attempt.FailureReason = response.Status == RtcResultStatus.Timeout
                    ? "reconnect_auth_timeout"
                    : "Reconnect auth failed.";
                retriedCount = _reconnectAttempt;
            }

            if (authOk)
            {
                if (!TryCommitReconnectAuthSuccess(
                    attempt,
                    response.Value.Payload))
                {
                    return;
                }

                SafeRaiseReloginCompleted(true, false, 0, retriedCount);
                StartHeartbeatWatchdog();
                return;
            }

            // 重连后重新认证失败：按一次失败的重连尝试处理，继续退避或进入 ReconnectFailed。
            FailReconnectAuth(attempt, attempt.FailureReason);
        }

        private bool TryCommitReconnectAuthSuccess(
            ReconnectAuthAttempt attempt,
            RtcValue authPayload)
        {
            long transitionVersion;
            bool telemetryEnabled;
            List<RecoveryLoginWaiter> recoveryWaiters;
            IDisposable reconnectSubscription;
            lock (_gate)
            {
                // Close or a newer reconnect attempt can win while subscription
                // cleanup runs outside the lock. Only the current attempt may
                // publish a successful reconnect.
                if (!IsCurrentReconnectAuthAttemptLocked(attempt)
                    || !attempt.ResultClaimed
                    || !attempt.AuthSucceeded
                    || attempt.Invalidated
                    || attempt.LifecycleFinished)
                {
                    return false;
                }

                telemetryEnabled = UpdateClientTelemetryState(authPayload);
                attempt.LifecycleFinished = true;
                reconnectSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                _reconnectAttempt = 0;
                _state = RtcRuntimeState.Connected;
                recoveryWaiters = DetachRecoveryLoginWaitersLocked();
                transitionVersion = RecordStatusTransitionLocked();
            }

            DisposeSubscription(reconnectSubscription);
            try
            {
                _tracing?.TrackConnectionState(
                    _sessionId,
                    _currentTransportEpoch.ToString(),
                    RtcRuntimeState.Reconnecting.ToString(),
                    RtcRuntimeState.Connected.ToString(),
                    0,
                    null,
                    null);
            }
            finally
            {
                SafeRaiseStatusChanged(
                    RtcRuntimeState.Connected,
                    transitionVersion);
            }

            // 重连汇合成功：在状态事件之后结束等待者（每个恰好一次成功回调）。
            ResolveRecoveryLoginWaiters(
                recoveryWaiters,
                RtcResult<RtcLoginResult>.Succeeded(
                    0,
                    new RtcLoginResult
                    {
                        ClientTelemetryEnabled = telemetryEnabled
                    }));

            return true;
        }

        private static int ExtractReconnectAuthErrorCode(
            RtcResult<RtcResponse> response,
            bool authOk)
        {
            if (response == null || authOk)
            {
                return 0;
            }

            int responseErrorCode = response.Error?.RawServerCode ?? 0;
            if (responseErrorCode != 0)
            {
                return responseErrorCode;
            }

            return response.IsSuccess
                ? ExtractRemoteErrorCode(response.Value?.Payload)
                : 0;
        }

        // 登录成功或重连成功时都要（重新）开始心跳巡检：记录当前时间为"最近一次收到心跳"的
        // 起点，然后调度第一次巡检。收到服务端 "control.ping" 会持续推进这个时间点（见
        // HandleTwoWayQuest）；超过阈值没收到就主动判定连接已死。
        // 8.12.10：每次启动递增 _heartbeatGeneration，CheckHeartbeat 只允许当前 generation
        // 继续调度——旧连接遗留的 timer 发现 generation 不符直接返回，防止多次重连后
        // 多条 watchdog 链并行。
        private void StartHeartbeatWatchdog()
        {
            int generation;
            lock (_gate)
            {
                _heartbeatRequestInFlight = false;
                _heartbeatRequestSentAtMs = 0;
                _nextHeartbeatAtMs = _monotonicClock.ElapsedMilliseconds;
                generation = ++_heartbeatGeneration;
            }

            SendHeartbeatPing(generation);
            ScheduleHeartbeatCheck(generation);
        }

        private void SendHeartbeatPing(int generation)
        {
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connected
                    || generation != _heartbeatGeneration
                    || _heartbeatRequestInFlight)
                {
                    return;
                }

                _heartbeatRequestInFlight = true;
                _heartbeatRequestSentAtMs = _monotonicClock.ElapsedMilliseconds;
            }

            SendCore(
                _heartbeatRequest,
                null,
                onCompletedSynchronously: result =>
                    CompleteHeartbeatPing(generation, result),
                isInternalRequest: true);
        }

        private void CompleteHeartbeatPing(
            int generation,
            RtcResult<RtcResponse> result)
        {
            bool shouldDisconnect = false;
            long pingRttMs = -1;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connected
                    || generation != _heartbeatGeneration
                    || !_heartbeatRequestInFlight)
                {
                    return;
                }

                long sentAtMs = _heartbeatRequestSentAtMs;
                _heartbeatRequestInFlight = false;
                _heartbeatRequestSentAtMs = 0;
                if (result != null && result.IsSuccess)
                {
                    pingRttMs = Math.Max(
                        0,
                        _monotonicClock.ElapsedMilliseconds - sentAtMs);
                    ObservePingServerTime(result.Value);
                    _nextHeartbeatAtMs =
                        _monotonicClock.ElapsedMilliseconds + HeartbeatPingIntervalMs;
                }
                else
                {
                    _pendingDisconnectReason = RtcCloseReason.Timeout;
                    _pendingDisconnectEpoch = _currentTransportEpoch;
                    shouldDisconnect = true;
                }
            }

            if (pingRttMs >= 0)
            {
                _tracing?.AggregatePingRtt(pingRttMs);
            }

            if (shouldDisconnect)
            {
                DisconnectTransportSafely("heartbeat request disconnect");
            }
        }

        private static void ObservePingServerTime(RtcResponse response)
        {
            if (response == null
                || response.Payload == null
                || response.Payload.Kind != RtcValueKind.Map)
            {
                return;
            }

            RtcValue value = response.Payload[RtcGateContract.PingServerTime];
            if (value != null && value.Kind == RtcValueKind.Int64)
            {
                PingServerTime.Value = value.Int64Value;
            }
        }

        private void ScheduleHeartbeatCheck(int generation)
        {
            var entry = new TimerEntry(generation);
            IDisposable oldSubscription;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connected || generation != _heartbeatGeneration)
                {
                    return;
                }

                oldSubscription = DetachTimerEntryLocked(ref _heartbeatEntry);
                _heartbeatEntry = entry;
            }

            IDisposable subscription;
            try
            {
                subscription = _timerScheduler.Schedule(
                    HeartbeatCheckInterval,
                    () => CheckHeartbeat(entry));
            }
            catch (Exception error)
            {
                _logger.Error("heartbeat schedule", error);
                lock (_gate)
                {
                    if (ReferenceEquals(_heartbeatEntry, entry))
                    {
                        _heartbeatEntry = null;
                    }
                }
                DisposeSubscription(oldSubscription);
                return;
            }

            bool keep;
            lock (_gate)
            {
                keep = _state == RtcRuntimeState.Connected
                    && generation == _heartbeatGeneration
                    && ReferenceEquals(_heartbeatEntry, entry);
                if (keep)
                {
                    entry.Subscription = subscription;
                }
            }

            DisposeSubscription(oldSubscription);
            if (!keep)
            {
                DisposeSubscription(subscription);
            }
        }

        private void CheckHeartbeat(TimerEntry entry)
        {
            bool timedOut = false;
            bool shouldSend = false;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Connected
                    || entry.Generation != _heartbeatGeneration
                    || !ReferenceEquals(_heartbeatEntry, entry))
                {
                    return; // 已不在 Connected，或已被更新的连接取代（旧 timer 直接退出）。
                }

                long now = _monotonicClock.ElapsedMilliseconds;
                if (_heartbeatRequestInFlight)
                {
                    timedOut = now - _heartbeatRequestSentAtMs > _heartbeatRequestTimeoutMs;
                }
                else
                {
                    shouldSend = now >= _nextHeartbeatAtMs;
                }
            }

            if (timedOut)
            {
                // 只切断当前连接（Disconnect，不是永久性的 Close），让真实的 Closed 事件走
                // OnTransportClosed 既有的断线处理路径（挂起请求判 TransportLost、转
                // Reconnecting、照常重连）——心跳看门狗不需要重复实现这条逻辑。
                bool shouldDisconnect = false;
                lock (_gate)
                {
                    if (_state == RtcRuntimeState.Connected
                        && entry.Generation == _heartbeatGeneration
                        && ReferenceEquals(_heartbeatEntry, entry))
                    {
                        _heartbeatRequestInFlight = false;
                        _heartbeatRequestSentAtMs = 0;
                        _pendingDisconnectReason = RtcCloseReason.Timeout;
                        _pendingDisconnectEpoch = _currentTransportEpoch;
                        shouldDisconnect = true;
                    }
                }
                if (shouldDisconnect)
                {
                    DisconnectTransportSafely("heartbeat watchdog disconnect");
                }
                return;
            }

            if (shouldSend)
            {
                SendHeartbeatPing(entry.Generation);
            }

            ScheduleHeartbeatCheck(entry.Generation);
        }

        private void OnReconnectFailed(string reason)
        {
            OnReconnectFailed(reason, false, 0);
        }

        private void OnReconnectFailed(string reason, bool stopRetry, int errorCode)
        {
            bool exhausted;
            bool enteringFailed = false;
            int retriedCount;
            lock (_gate)
            {
                if (_state != RtcRuntimeState.Reconnecting)
                {
                    return;
                }

                _reconnectAttempt++;
                retriedCount = _reconnectAttempt;
                exhausted = stopRetry || _reconnectAttempt >= _maxReconnectAttempts;
                if (exhausted)
                {
                    enteringFailed = true;
                }
                else
                {
                    _lastReconnectErrorCode = errorCode != 0
                        ? errorCode
                        : RtcReconnectUnknownError;
                }
            }

            if (enteringFailed)
            {
                IDisposable reconnectSubscription;
                List<RecoveryLoginWaiter> recoveryWaiters;
                RtcRuntimeState previousState;
                bool stateChanged = false;
                long transitionVersion = 0;
                lock (_gate)
                {
                    if (_state != RtcRuntimeState.Reconnecting)
                    {
                        // Close 等已在两次临界区之间终结状态；等待者已由该路径收尾。
                        return;
                    }

                    previousState = _state;
                    reconnectSubscription = DetachTimerEntryLocked(ref _reconnectEntry);
                    // 摘除等待者与状态切换必须在同一 _gate 临界区内完成：
                    // 若拆开，窗口期内的新 Login 会看到 Reconnecting 并加入已被
                    // 清空的等待队列，之后没有任何结局会结束它。
                    recoveryWaiters = DetachRecoveryLoginWaitersLocked();
                    stateChanged = ChangeState(RtcRuntimeState.ReconnectFailed);
                    if (stateChanged)
                    {
                        transitionVersion = RecordStatusTransitionLocked();
                    }
                }

                DisposeSubscription(reconnectSubscription);
                string failureReason = string.IsNullOrEmpty(reason)
                    ? "reconnect_failed"
                    : reason;
                int terminalErrorCode = stopRetry && errorCode != 0
                    ? errorCode
                    : RtcReconnectUnknownError;
                if (stateChanged)
                {
                    try
                    {
                        _tracing?.TrackConnectionState(
                            _sessionId,
                            _currentTransportEpoch.ToString(),
                            previousState.ToString(),
                            RtcRuntimeState.ReconnectFailed.ToString(),
                            0,
                            null,
                            failureReason,
                            false,
                            null);
                    }
                    finally
                    {
                        SafeRaiseStatusChanged(
                            RtcRuntimeState.ReconnectFailed,
                            transitionVersion);
                    }
                }
                SafeRaiseReloginCompleted(
                    false,
                    false,
                    terminalErrorCode,
                    retriedCount,
                    failureReason);
                // 重连汇合失败：在 ReloginCompleted 之后、SessionClosed 之前结束等待者。
                ResolveRecoveryLoginWaiters(
                    recoveryWaiters,
                    RtcResult<RtcLoginResult>.Failed(
                        0,
                        RtcResultStatus.Failed,
                        new RtcError(
                            RtcErrorCode.NotConnected,
                            0,
                            "Reconnect failed while login was waiting.",
                            false)));
                TryMarkSessionEnded(
                    "session_closed",
                    "remote_close",
                    terminalErrorCode,
                    false,
                    failureReason);
                RaiseSessionClosedOnce(terminalErrorCode);
                return;
            }

            // 尚未耗尽：一次失败的尝试后继续退避（不触发 ReloginCompleted，等最终结果）。
            SafeRaiseReloginCompleted(
                false,
                true,
                RtcReconnectUnknownError,
                retriedCount,
                string.IsNullOrEmpty(reason) ? "reconnect_failed" : reason);
            ScheduleReconnectAttempt();
        }

        private static string ToReconnectTrigger(RtcCloseReason reason)
        {
            switch (reason)
            {
                case RtcCloseReason.RemoteEof: return "remote_closed";
                case RtcCloseReason.SocketError: return "socket_error";
                case RtcCloseReason.Timeout: return "timeout";
                case RtcCloseReason.SendQueueFull:
                case RtcCloseReason.FramingError: return "socket_error";
                default: return "unknown";
            }
        }

        // Reconnect/session-close fallback code from the RTC TLV contract.
        // Keep the raw value in the AOT-owned TLV table instead of referencing Compat aliases.
        private const int RtcReconnectUnknownError = RtcRawErrorCodes.TLVCoreUnknownError;

        private sealed class PushObserverSubscription : IDisposable
        {
            private readonly RtcRuntime _owner;
            private readonly Action<string, RtcDecodedPushMessage> _observer;
            private int _disposed;

            public PushObserverSubscription(
                RtcRuntime owner,
                Action<string, RtcDecodedPushMessage> observer)
            {
                _owner = owner;
                _observer = observer;
            }

            public void Dispose()
            {
                if (Interlocked.Exchange(ref _disposed, 1) != 0)
                {
                    return;
                }

                lock (_owner._gate)
                {
                    _owner._pushObserver -= _observer;
                }
            }
        }

        private sealed class GenericPushSubscription : IDisposable
        {
            private readonly RtcRuntime _owner;
            private readonly string _method;
            private readonly Action<RtcPushEnvelope> _handler;
            private int _disposed;

            public GenericPushSubscription(RtcRuntime owner, string method, Action<RtcPushEnvelope> handler)
            {
                _owner = owner;
                _method = method;
                _handler = handler;
            }

            public void Dispose()
            {
                if (Interlocked.Exchange(ref _disposed, 1) != 0)
                {
                    return;
                }

                lock (_owner._gate)
                {
                    if (_owner._pushRoutes.TryGetValue(_method, out PushRoute route)
                        && (route.Kind == PushRouteKind.Generic
                            || route.Kind == PushRouteKind.Mixed))
                    {
                        Action<RtcPushEnvelope> updated = route.GenericHandler - _handler;
                        if (updated == null)
                        {
                            if (route.TypedHandler != null)
                            {
                                route.Kind = PushRouteKind.Typed;
                                route.GenericHandler = null;
                            }
                            else
                            {
                                _owner._pushRoutes.Remove(_method);
                            }
                        }
                        else
                        {
                            route.GenericHandler = updated;
                        }
                    }
                }
            }
        }

        private sealed class TypedPushSubscription : IDisposable
        {
            private readonly RtcRuntime _owner;
            private readonly string _method;
            private readonly Action<RtcDecodedPushMessage> _handler;
            private int _disposed;

            public TypedPushSubscription(
                RtcRuntime owner,
                string method,
                Action<RtcDecodedPushMessage> handler)
            {
                _owner = owner;
                _method = method;
                _handler = handler;
            }

            public void Dispose()
            {
                if (Interlocked.Exchange(ref _disposed, 1) != 0)
                {
                    return;
                }

                lock (_owner._gate)
                {
                    if (_owner._pushRoutes.TryGetValue(_method, out PushRoute route)
                        && (route.Kind == PushRouteKind.Typed
                            || route.Kind == PushRouteKind.Mixed))
                    {
                        Action<RtcDecodedPushMessage> updated = route.TypedHandler - _handler;
                        if (updated == null)
                        {
                            if (route.GenericHandler != null)
                            {
                                route.Kind = PushRouteKind.Generic;
                                route.TypedHandler = null;
                            }
                            else
                            {
                                _owner._pushRoutes.Remove(_method);
                            }
                        }
                        else
                        {
                            route.TypedHandler = updated;
                        }
                    }
                }
            }
        }
    }
